// A plan's UnitProfile as the records to write into a slot. Everything a record holds comes
// from the plan and the unit's device data (its pins, stick angle and X fact); nothing here
// knows which hand is which beyond what the device says.

import type {
  AzeronDevice,
  KeyCode,
  Mod,
  MouseButton,
  PadControl,
  PinPlan,
  Press,
  ScrollDirection,
  Signal,
  StickDirection as CoreStickDirection,
  StickDirections,
  UnitProfile,
} from '@helmarray/core';
import type {
  Block,
  ButtonRecord,
  StickRecord,
  StickTuning,
  UnitRecord,
  WheelTap,
} from './records';
import { ProtocolError } from './report';

/**
 * The app's input id for each pin. The same on both units and on firmware 111 and 112: every
 * slot read or written in reference/ holds exactly these (test/unit-records.test.ts).
 */
export const INPUT_ID_BY_PIN: ReadonlyMap<number, number> = new Map([
  [2, 1], [3, 2], [4, 3], [5, 4], [8, 5], [9, 6], [10, 7], [11, 8], [14, 9], [15, 10],
  [16, 11], [17, 12], [13, 13], [23, 14], [24, 15], [25, 16], [26, 17], [22, 18], [27, 19],
  [19, 20], [37, 22], [32, 23], [31, 24], [34, 28], [35, 29], [36, 30], [33, 31], [6, 36],
  [1, 37], [7, 38], [20, 41],
]); // prettier-ignore

/** The unit's code for each key: `0xF000 | HID usage`, a modifier `0xE000 | bit`. */
export const UNIT_KEY_CODES: Readonly<Record<KeyCode, number>> = {
  A: 0xf004, B: 0xf005, C: 0xf006, D: 0xf007, E: 0xf008, F: 0xf009, G: 0xf00a, H: 0xf00b,
  I: 0xf00c, J: 0xf00d, K: 0xf00e, L: 0xf00f, M: 0xf010, N: 0xf011, O: 0xf012, P: 0xf013,
  Q: 0xf014, R: 0xf015, S: 0xf016, T: 0xf017, U: 0xf018, V: 0xf019, W: 0xf01a, X: 0xf01b,
  Y: 0xf01c, Z: 0xf01d,
  '1': 0xf01e, '2': 0xf01f, '3': 0xf020, '4': 0xf021, '5': 0xf022, '6': 0xf023, '7': 0xf024,
  '8': 0xf025, '9': 0xf026, '0': 0xf027,
  Enter: 0xf028, Esc: 0xf029, Backspace: 0xf02a, Tab: 0xf02b, Space: 0xf02c,
  '-': 0xf02d, '=': 0xf02e, '[': 0xf02f, ']': 0xf030, '\\': 0xf031, ';': 0xf033, "'": 0xf034,
  '`': 0xf035, ',': 0xf036, '.': 0xf037, '/': 0xf038, Caps: 0xf039,
  F1: 0xf03a, F2: 0xf03b, F3: 0xf03c, F4: 0xf03d, F5: 0xf03e, F6: 0xf03f, F7: 0xf040,
  F8: 0xf041, F9: 0xf042, F10: 0xf043, F11: 0xf044, F12: 0xf045,
  PrintScreen: 0xf046, ScrollLock: 0xf047, Pause: 0xf048, Insert: 0xf049, Home: 0xf04a,
  PageUp: 0xf04b, Del: 0xf04c, End: 0xf04d, PageDown: 0xf04e,
  Right: 0xf04f, Left: 0xf050, Down: 0xf051, Up: 0xf052,
  NumLock: 0xf053, NumDivide: 0xf054, NumMultiply: 0xf055, NumSubtract: 0xf056, NumAdd: 0xf057,
  NumEnter: 0xf058, Num1: 0xf059, Num2: 0xf05a, Num3: 0xf05b, Num4: 0xf05c, Num5: 0xf05d,
  Num6: 0xf05e, Num7: 0xf05f, Num8: 0xf060, Num9: 0xf061, Num0: 0xf062, NumDecimal: 0xf063,
  Menu: 0xf065,
  F13: 0xf068, F14: 0xf069, F15: 0xf06a, F16: 0xf06b, F17: 0xf06c, F18: 0xf06d, F19: 0xf06e,
  F20: 0xf06f, F21: 0xf070, F22: 0xf071, F23: 0xf072, F24: 0xf073,
  LCtrl: 0xe001, LShift: 0xe002, LAlt: 0xe004, LWin: 0xe008,
  RCtrl: 0xe010, RShift: 0xe020, RAlt: 0xe040, RWin: 0xe080,
}; // prettier-ignore

const MOD_CODES: Readonly<Record<Mod, number>> = { ctrl: 0xe001, shift: 0xe002, alt: 0xe004 };

/**
 * Mouse buttons by number: left 1 and right 3 confirmed in play, middle 2 in the app, back 4
 * and forward 5 written by the app and pressed in a browser (2026-11-19).
 */
const MOUSE_NUMBERS: Readonly<Record<MouseButton, number>> = {
  left: 1,
  middle: 2,
  right: 3,
  back: 4,
  forward: 5,
};

/**
 * Xbox buttons by their XInput bit, as the app's export and wire carry them (A 0x1000 seen).
 * The triggers are their own type, 1 left and 2 right. The stick directions as buttons were
 * never seen sent, so they are not here.
 */
const PAD_BITS: Partial<Record<PadControl, number>> = {
  DPAD_UP: 0x0001,
  DPAD_DOWN: 0x0002,
  DPAD_LEFT: 0x0004,
  DPAD_RIGHT: 0x0008,
  START: 0x0010,
  BACK: 0x0020,
  LS: 0x0040,
  RS: 0x0080,
  LB: 0x0100,
  RB: 0x0200,
  A: 0x1000,
  B: 0x2000,
  X: 0x4000,
  Y: 0x8000,
};
const TRIGGERS: Partial<Record<PadControl, number>> = { LT: 1, RT: 2 };

/** The app's own defaults, as every captured slot that left them alone holds them. */
const DEFAULT_LONG_DELAY = 500;
const DEFAULT_DOUBLE_DELAY = 150;
const STILL_INTERVAL = 150;
/** The stick's travel, which the deadzones are a share of. */
const STICK_TRAVEL = 512;

const EMPTY: Block = {
  type: 'none',
  keys: [],
  mods: [],
  hold: false,
  holdTime: 0,
  turbo: false,
  turboInterval: 0,
};

function scroll(dir: ScrollDirection, speed: number, where: string): WheelTap {
  if (!Number.isInteger(speed) || speed < 0 || speed > 100) {
    throw new ProtocolError(`${where}: a scroll speed is 0 to 100, not ${speed}.`);
  }
  // The app's own sum, sent whole: (100 - speed) × 1.5 on the moving axis, 150 on the other.
  const moving = Math.trunc((100 - speed) * 1.5);
  const vertical = dir === 'up' || dir === 'down';
  return {
    type: 'wheel',
    x: dir === 'right' ? 1 : dir === 'left' ? -1 : 0,
    y: dir === 'up' ? 1 : dir === 'down' ? -1 : 0,
    interval: vertical ? STILL_INTERVAL : moving,
    yInterval: vertical ? moving : STILL_INTERVAL,
  };
}

function blockFor(signal: Signal, pin: PinPlan, where: string): Block {
  const base: Block = {
    ...EMPTY,
    hold: pin.latch,
    turbo: pin.turbo !== false,
    turboInterval: pin.turbo === false ? 0 : pin.turbo.interval,
  };
  switch (signal.kind) {
    case 'key':
      return {
        ...base,
        type: 'key',
        keys: [UNIT_KEY_CODES[signal.code]],
        mods: (signal.mods ?? []).map((m) => MOD_CODES[m]),
      };
    case 'mouse': {
      return { ...base, type: 'mouse', keys: [MOUSE_NUMBERS[signal.button]] };
    }
    case 'pad': {
      const bit = PAD_BITS[signal.control];
      if (bit !== undefined) return { ...base, type: 'pad', keys: [bit] };
      const trigger = TRIGGERS[signal.control];
      if (trigger !== undefined) return { ...base, type: 'trigger', keys: [trigger] };
      throw new ProtocolError(
        `${where}: Xbox ${signal.control} on a button was never captured, so it can't be sent.`,
      );
    }
    case 'scroll':
      throw new ProtocolError(`${where}: a unit scrolls only on a tap.`);
    case 'macro':
      throw new ProtocolError(`${where}: macros are typed by the app, not stored on a unit.`);
  }
}

function pressBlock(pin: PinPlan, press: Press, where: string): Block | WheelTap {
  const signal = pin.presses[press];
  if (!signal) return EMPTY;
  if (signal.kind === 'scroll' && press === 'tap') {
    // A stored scroll has no room for hold or turbo: refused rather than dropped unsaid.
    if (pin.latch || pin.turbo !== false) {
      throw new ProtocolError(`${where}: a scroll can't latch or repeat on the unit.`);
    }
    return scroll(signal.dir, signal.speed, where);
  }
  return blockFor(signal, pin, `${where} ${press}`);
}

function buttonRecord(pin: PinPlan, id: number): ButtonRecord {
  const where = pin.control;
  const long = pressBlock(pin, 'long', where);
  const double = pressBlock(pin, 'double', where);
  if (long.type === 'wheel' || double.type === 'wheel') {
    // Stryker disable next-line StringLiteral: unreachable message; pressBlock hands back a scroll only for a tap, the guard only narrows the type
    throw new ProtocolError(`${where}: a unit scrolls only on a tap.`);
  }
  return {
    kind: 'button',
    id,
    pinOne: pin.pin,
    pinTwo: pin.pinTwo ?? 255,
    tap: pressBlock(pin, 'tap', where),
    long,
    double,
    longDelay: DEFAULT_LONG_DELAY,
    doubleDelay: DEFAULT_DOUBLE_DELAY,
  };
}

function percentOfTravel(value: number, what: string, where: string): number {
  if (!Number.isInteger(value) || value < 0 || value > 99) {
    throw new ProtocolError(`${where}: the ${what} is 0 to 99 percent, not ${value}.`);
  }
  return Math.round((value * STICK_TRAVEL) / 100);
}

function stickRecord(profile: UnitProfile, device: AzeronDevice): StickRecord {
  const position = device.positions.find((p) => p.name === 'stick');
  const id = position && INPUT_ID_BY_PIN.get(position.pin);
  if (!position || position.pinTwo === undefined || id === undefined) {
    throw new ProtocolError(`${device.name} has no stick on the pins the app writes.`);
  }
  const s = profile.stick;
  const where = `${profile.hand === 'left' ? 'L' : 'R'}.stick`;
  const mode = s.mode === 'keys' ? 'keys' : s.mode === 'mouse' ? 'mouse' : 'pad';
  if (s.sensitivity !== undefined && mode !== 'mouse') {
    throw new ProtocolError(`${where}: sensitivity is for a stick that moves the mouse.`);
  }
  const lowerLimit = percentOfTravel(s.deadzone ?? 0, 'deadzone', where);
  const upperLimit = percentOfTravel(100 - (s.outerEdge ?? 100), 'outer edge', where);
  if (lowerLimit + upperLimit >= STICK_TRAVEL) {
    throw new ProtocolError(`${where}: the deadzone and outer edge leave the stick no travel.`);
  }
  const tuning: StickTuning = {
    upperLimit,
    lowerLimit,
    angle: s.angle,
    sensitivity: 3,
    verticalCone: 45,
    horizontalCone: 45,
    isEightDirectionalTrigger: false,
    mouseSensitivity: s.sensitivity ?? 5,
    analogThrottle: 0,
    isAnalogSmoothing: false,
    triggerMagnitude: 4,
    isCombinedAnalog: false,
    combinedAnalogMagnitude: 6,
    isHoldTrigger: false,
    holdMagnitude: 9,
    holdType: 1,
    holdKeys: [UNIT_KEY_CODES.LShift],
    rotateStickButtonId: 0,
    isAngleLock: false,
    lockZoneAngle: 70,
    lockZoneSize: 30,
    // As an Xbox stick, this picks which one: set, the right stick, on either unit (written and
    // shown so by the app, 2026-11-19). In key or mouse mode the app sets it on a right unit.
    isRightAnalog: mode === 'pad' ? s.mode === 'pad-right' : profile.hand === 'right',
    invertXAxis: s.invertX,
    invertYAxis: s.invertY ?? false,
  };
  return {
    kind: 'stick',
    id,
    pinOne: position.pin,
    pinTwo: position.pinTwo,
    mode,
    tuning,
    directions:
      mode === 'keys' ? directionKeys(s.directions ?? {}, tuning.isRightAnalog, where) : {},
  };
}

/** core's four directions; `azeron` may import only core's types, so they're listed here. */
const CORE_STICK_DIRECTIONS: readonly CoreStickDirection[] = ['up', 'down', 'left', 'right'];

/**
 * A key-mode stick's direction keys, in the block the unit reads: `isRightAnalog` set reads the
 * right block, clear the left (legacy CLAUDE.md, export format rules: writing the other block
 * compiles and does nothing on the hardware). Each direction is [key, modifier, modifier].
 */
function directionKeys(
  directions: StickDirections,
  rightBlock: boolean,
  where: string,
): StickRecord['directions'] {
  const block = rightBlock ? 'right' : 'left';
  const out: StickRecord['directions'] = {};
  for (const direction of CORE_STICK_DIRECTIONS) {
    const signal = directions[direction];
    if (signal === undefined) continue;
    if (signal.kind !== 'key') {
      throw new ProtocolError(
        `${where} ${direction}: a stick direction sends a key, nothing else.`,
      );
    }
    const mods = (signal.mods ?? []).map((m) => MOD_CODES[m]);
    if (mods.length > 2) {
      throw new ProtocolError(
        `${where} ${direction}: a stick direction holds two modifiers at most.`,
      );
    }
    out[`${block}.${direction}`] = [UNIT_KEY_CODES[signal.code], ...mods];
  }
  return out;
}

/**
 * Every record a slot gets for a unit's profile, by input id. Pins the press test found wired
 * to nothing and the profile switch on pin 0 are left alone, as the app leaves them.
 */
export function unitRecords(profile: UnitProfile, device: AzeronDevice): UnitRecord[] {
  if (profile.deviceId !== device.id || profile.hand !== device.hand) {
    throw new ProtocolError(`This profile is for ${profile.deviceId}, not ${device.id}.`);
  }
  const records: UnitRecord[] = [stickRecord(profile, device)];
  for (const pin of profile.pins) {
    if (pin.pin === 0 || device.unknownPins.includes(pin.pin)) continue;
    const id = INPUT_ID_BY_PIN.get(pin.pin);
    if (id === undefined)
      throw new ProtocolError(`${pin.control}: pin ${pin.pin} has no input id.`);
    records.push(buttonRecord(pin, id));
  }
  return records.sort((a, b) => a.id - b.id);
}

packages/azeron/src/records.ts.source:
// What OBM_COPY carries: one input record into a slot (reference/guides/unit-protocol.md, "An
// input record, as written" and "Firmware 112"). Records are in the unit's own terms: its key
// codes and type bytes. Every layout here reproduces the Azeron app's own records byte for
// byte (test/unit-records.test.ts). All 16-bit values go big-endian.

import { ProtocolError } from './report';

/** What a press sends, by the unit's type byte. */
export const BLOCK_TYPES = {
  key: 1,
  disabled: 6,
  none: 11,
  mouse: 15,
  pad: 0x16,
  trigger: 0x17,
} as const;
export type BlockType = keyof typeof BLOCK_TYPES;

/**
 * One press of a button. `keys` are the unit's codes: a key's `0xF000 | HID usage`, a mouse
 * button's number, an Xbox button's XInput bit, or a trigger's 1 (left) / 2 (right). `mods` are
 * modifier codes (`0xE000 | bit`). Missing entries are 0.
 */
export interface Block {
  type: BlockType;
  keys: readonly number[];
  mods: readonly number[];
  /** Hold to latch: the key stays down until pressed again. */
  hold: boolean;
  holdTime: number;
  turbo: boolean;
  turboInterval: number;
}

/**
 * A tap that scrolls. Directions are 1 or -1 on the axis that moves (x right, y up), 0 on the
 * other; each interval is the time between steps, the app's `(100 - speed) × 1.5`, 150 still.
 */
export interface WheelTap {
  type: 'wheel';
  x: number;
  y: number;
  interval: number;
  yInterval: number;
}

export interface ButtonRecord {
  kind: 'button';
  id: number;
  pinOne: number;
  /** 255 for a button on one pin. */
  pinTwo: number;
  tap: Block | WheelTap;
  long: Block;
  double: Block;
  /** How long a press must be to be long, in ms (the app's default is 500). */
  longDelay: number;
  /** How long to wait for a second tap, in ms (the app's default is 150). */
  doubleDelay: number;
}

export const STICK_TYPES = { keys: 4, pad: 0x15, mouse: 0x28 } as const;
export type StickType = keyof typeof STICK_TYPES;

/** The stick's tuning, in the order the app sends it. Names are the app's export fields. */
export interface StickTuning {
  upperLimit: number;
  lowerLimit: number;
  /** Degrees, signed: -1 is none. */
  angle: number;
  sensitivity: number;
  verticalCone: number;
  horizontalCone: number;
  isEightDirectionalTrigger: boolean;
  mouseSensitivity: number;
  analogThrottle: number;
  isAnalogSmoothing: boolean;
  triggerMagnitude: number;
  isCombinedAnalog: boolean;
  combinedAnalogMagnitude: number;
  isHoldTrigger: boolean;
  holdMagnitude: number;
  holdType: number;
  /** As sent: Shift is 0xE002; the app sent its "17" as 0x0011. */
  holdKeys: readonly number[];
  rotateStickButtonId: number;
  isAngleLock: boolean;
  lockZoneAngle: number;
  lockZoneSize: number;
  isRightAnalog: boolean;
  invertXAxis: boolean;
  invertYAxis: boolean;
}

/** The stick's 16 directions, in the order sent, each a key and two modifiers. */
export const STICK_DIRECTIONS = [
  'left.up',
  'left.right',
  'left.down',
  'left.left',
  'right.up',
  'right.right',
  'right.down',
  'right.left',
  'left.up_right',
  'left.up_left',
  'left.down_left',
  'left.down_right',
  'right.up_right',
  'right.up_left',
  'right.down_left',
  'right.down_right',
] as const;
export type StickDirection = (typeof STICK_DIRECTIONS)[number];

export interface StickRecord {
  kind: 'stick';
  id: number;
  pinOne: number;
  pinTwo: number;
  mode: StickType;
  tuning: StickTuning;
  /** Key codes per direction: [key, modifier, modifier]. Missing directions send nothing. */
  directions: Partial<Record<StickDirection, readonly number[]>>;
}

export type UnitRecord = ButtonRecord | StickRecord;

export const BUTTON_RECORD_LENGTH = 68;
export const WHEEL_RECORD_LENGTH = 55;
export const STICK_RECORD_LENGTH = 134;

class Writer {
  private readonly bytes: number[] = [];
  constructor(private readonly where: string) {}
  u8(value: number, what: string) {
    this.check(value, 0, 0xff, what);
    this.bytes.push(value);
  }
  i8(value: number, what: string) {
    this.check(value, -0x80, 0x7f, what);
    this.bytes.push(value & 0xff);
  }
  u16(value: number, what: string) {
    this.check(value, 0, 0xffff, what);
    this.bytes.push(value >> 8, value & 0xff);
  }
  i16(value: number, what: string) {
    this.check(value, -0x8000, 0x7fff, what);
    this.u16(value & 0xffff, what);
  }
  flag(value: boolean) {
    this.bytes.push(value ? 1 : 0);
  }
  list(values: readonly number[], count: number, what: string) {
    if (values.length > count) {
      throw new ProtocolError(
        `${this.where}: ${what} has ${values.length} entries; it holds ${count}.`,
      );
    }
    for (let i = 0; i < count; i++) this.u16(values[i] ?? 0, what);
  }
  done(length: number): Uint8Array {
    // Stryker disable next-line BlockStatement,ConditionalExpression: unreachable guard; every encoder writes a fixed number of fields
    if (this.bytes.length !== length) {
      // Stryker disable next-line StringLiteral,CallExpression: unreachable message; every encoder writes a fixed number of fields
      throw new ProtocolError(`${this.where} came to ${this.bytes.length} bytes, not ${length}.`);
    }
    return Uint8Array.from(this.bytes);
  }
  private check(value: number, min: number, max: number, what: string) {
    if (!Number.isInteger(value) || value < min || value > max) {
      throw new ProtocolError(`${this.where}: ${what} is ${value}, which doesn't fit.`);
    }
  }
}

function block(w: Writer, b: Block, delay: number | undefined, what: string) {
  // Stryker disable next-line StringLiteral: a block's type byte is one of six constants that always fit, so its label is never printed
  w.u8(BLOCK_TYPES[b.type], `${what} type`);
  w.list(b.keys, 4, `${what} keys`);
  w.list(b.mods, 3, `${what} modifiers`);
  w.flag(b.hold);
  if (delay !== undefined) w.u16(delay, `${what} delay`);
  w.u16(b.holdTime, `${what} hold time`);
  w.flag(b.turbo);
  w.u8(b.turboInterval, `${what} turbo interval`);
}

function encodeButton(slot: number, r: ButtonRecord): Uint8Array {
  const w = new Writer(`input ${r.id}`);
  w.u8(slot, 'slot');
  w.u8(r.id, 'id');
  w.u8(r.pinOne, 'pin');
  w.u8(r.pinTwo, 'second pin');
  if (r.tap.type === 'wheel') {
    // Stryker disable next-line StringLiteral: a scroll's tap type 0x23 always fits a byte, so its label is never printed
    w.u8(0x23, 'tap type');
    w.i8(r.tap.x, 'scroll x');
    w.i8(r.tap.y, 'scroll y');
    w.u16(r.tap.interval, 'scroll interval');
    w.u16(r.tap.yInterval, 'scroll y interval');
  } else {
    block(w, r.tap, undefined, 'tap');
  }
  block(w, r.long, r.longDelay, 'long press');
  block(w, r.double, r.doubleDelay, 'double tap');
  return w.done(r.tap.type === 'wheel' ? WHEEL_RECORD_LENGTH : BUTTON_RECORD_LENGTH);
}

function encodeStick(slot: number, r: StickRecord): Uint8Array {
  const w = new Writer(`stick ${r.id}`);
  const t = r.tuning;
  w.u8(slot, 'slot');
  w.u8(r.id, 'id');
  w.u8(r.pinOne, 'pin');
  w.u8(r.pinTwo, 'second pin');
  // Stryker disable next-line StringLiteral: a stick's type byte is one of three constants that always fit, so its label is never printed
  w.u8(STICK_TYPES[r.mode], 'type');
  w.u16(t.upperLimit, 'upper limit');
  w.u16(t.lowerLimit, 'lower limit');
  w.i16(t.angle, 'angle');
  w.u16(t.sensitivity, 'sensitivity');
  w.u8(t.verticalCone, 'vertical cone');
  w.u8(t.horizontalCone, 'horizontal cone');
  w.flag(t.isEightDirectionalTrigger);
  w.u8(t.mouseSensitivity, 'mouse sensitivity');
  w.u8(t.analogThrottle, 'analog throttle');
  w.flag(t.isAnalogSmoothing);
  w.u8(t.triggerMagnitude, 'trigger magnitude');
  w.flag(t.isCombinedAnalog);
  w.u8(t.combinedAnalogMagnitude, 'combined magnitude');
  w.flag(t.isHoldTrigger);
  w.u8(t.holdMagnitude, 'hold magnitude');
  w.u8(t.holdType, 'hold type');
  w.list(t.holdKeys, 3, 'hold keys');
  w.u8(t.rotateStickButtonId, 'rotate button');
  w.flag(t.isAngleLock);
  w.u8(t.lockZoneAngle, 'lock zone angle');
  w.u8(t.lockZoneSize, 'lock zone size');
  w.flag(t.isRightAnalog);
  w.flag(t.invertXAxis);
  w.flag(t.invertYAxis);
  for (const direction of STICK_DIRECTIONS) w.list(r.directions[direction] ?? [], 3, direction);
  return w.done(STICK_RECORD_LENGTH);
}

/** The OBM_COPY payload for one record into a slot. */
export function encodeRecord(slot: number, record: UnitRecord): Uint8Array {
  return record.kind === 'stick' ? encodeStick(slot, record) : encodeButton(slot, record);
}

/** The longest name a unit was seen to keep. */
export const MAX_PROFILE_NAME = 19;

/** PROFILE_NAME's payload: `[slot][length][name]`, printable ASCII, 1 to 19 characters. */
export function profileNamePayload(slot: number, name: string): Uint8Array {
  if (!Number.isInteger(slot) || slot < 0 || slot > 0xff) {
    throw new ProtocolError(`Slot ${slot} is not one a unit has.`);
  }
  const bytes = Array.from(name, (ch) => ch.charCodeAt(0));
  if (bytes.length === 0 || bytes.length > MAX_PROFILE_NAME) {
    throw new ProtocolError(`A unit keeps a name of 1 to ${MAX_PROFILE_NAME} characters.`);
  }
  if (bytes.some((b) => b < 0x20 || b > 0x7e)) {
    throw new ProtocolError(`A unit keeps only plain letters, digits and punctuation in a name.`);
  }
  return Uint8Array.from([slot, bytes.length, ...bytes]);
}

packages/azeron/src/report.ts.source:
// The Cyborg II's configuration reports, as the Azeron app sends and receives them
// (reference/guides/unit-protocol.md, "Reports" and "Commands"). Only commands the app was
// seen to send, with the payloads it was seen to send, can be built.

/** Every report is 64 bytes. A host report starts with report id 0. */
export const REPORT_LENGTH = 64;
const HEADER = 7;
/** Payload bytes one report carries. */
export const PART_CAPACITY = REPORT_LENGTH - HEADER;

/** The app's command table, by the command byte of a report. Names are the app's own. */
export const Command = {
  KEYPAD_DETAILS: 0x02,
  FIRMWARE_VERSION: 0x05,
  OBM_COPY: 0x0b,
  HARDWARE_PROFILE_INDEX: 0x0e,
  PROFILE_NAME: 0x10,
  SWITCH_PROFILE: 0x1a,
  DELETE_PROFILE: 0x1c,
  CHECK_PROFILE: 0x1d,
  REQUEST_PROFILE: 0x1e,
  PROFILE_LIMIT: 0x1f,
  PROFILE_INPUT_PIECE: 0x2b,
  PROFILE_PAYLOAD_V2: 0x2e,
  RELEASED_ALL_BUTTONS: 0x34,
  DEVICE_DIAGNOSTICS: 0x35,
  JOYSTICK_POSITION: 0x37,
  BUTTON_POSITION: 0x39,
} as const;
export type CommandName = keyof typeof Command;

/**
 * The commands this app may send: each one the Azeron app was seen to send, in the shape built
 * here. Nothing else can be put on the wire. Never: RESET, DFU, UPDATE_DEVICE_ID,
 * KEYPAD_DETAILS_SAVE, REQUEST_PROFILE (it answers with the running slot whatever is asked).
 */
export const SENDABLE: readonly CommandName[] = [
  'FIRMWARE_VERSION',
  'KEYPAD_DETAILS',
  'PROFILE_LIMIT',
  'HARDWARE_PROFILE_INDEX',
  'PROFILE_PAYLOAD_V2',
  'PROFILE_INPUT_PIECE',
  'CHECK_PROFILE',
  'PROFILE_NAME',
  'OBM_COPY',
  'SWITCH_PROFILE',
  'DELETE_PROFILE',
];

export class ProtocolError extends Error {}

/** The sequence number after `seq`. The app counts 0 to 254 and wraps: it never sends 255. */
export const nextSeq = (seq: number, step = 1): number => (seq + step) % 255;

/** The longest payload the app was seen to send fits a one-byte length. */
const MAX_PAYLOAD = 0xff;

/**
 * Host reports for one command: `[0][length][command][seq][parts][part][part length][payload…]`,
 * zero padded. A payload over 57 bytes goes in parts, each with the whole length in byte 1,
 * numbered from 1, the sequence counting on by one per part.
 */
export function hostReports(name: CommandName, seq: number, payload: Uint8Array): Uint8Array[] {
  if (!SENDABLE.includes(name))
    throw new ProtocolError(`${name} is not a command helmArray sends.`);
  if (payload.length > MAX_PAYLOAD) {
    throw new ProtocolError(`A ${payload.length}-byte payload is longer than any the app sent.`);
  }
  if (!Number.isInteger(seq) || seq < 0 || seq > 254) {
    throw new ProtocolError(`Sequence ${seq} is not one the app sends.`);
  }
  const parts = Math.max(1, Math.ceil(payload.length / PART_CAPACITY));
  return Array.from({ length: parts }, (_, i) => {
    const chunk = payload.subarray(i * PART_CAPACITY, (i + 1) * PART_CAPACITY);
    const report = new Uint8Array(REPORT_LENGTH);
    report.set([0, payload.length, Command[name], nextSeq(seq, i), parts, i + 1, chunk.length]);
    report.set(chunk, HEADER);
    return report;
  });
}

/** A report from the unit. */
export interface UnitReport {
  /** The whole payload's length, from bytes 0–1. */
  length: number;
  command: number;
  seq: number;
  /** In a profile stream, the index of the stream's last item; otherwise the part count. */
  parts: number;
  /** In a profile stream, the item this report belongs to; otherwise the part number. */
  part: number;
  payload: Uint8Array;
}

/** `[length lo][length hi][command][seq][parts][part][part length][payload…]`. */
export function parseUnitReport(report: Uint8Array): UnitReport {
  if (report.length !== REPORT_LENGTH) {
    throw new ProtocolError(`A unit report is ${REPORT_LENGTH} bytes, not ${report.length}.`);
  }
  const at = (i: number) => report[i] ?? 0;
  const partLength = at(6);
  if (HEADER + partLength > REPORT_LENGTH) {
    throw new ProtocolError(`A unit report claims ${partLength} bytes it doesn't have.`);
  }
  return {
    length: at(0) | (at(1) << 8),
    command: at(2),
    seq: at(3),
    parts: at(4),
    part: at(5),
    payload: report.slice(HEADER, HEADER + partLength),
  };
}

/** A host report, as a fake unit reads it: `[0][length][command][seq][parts][part][part length]…`. */
export function parseHostReport(report: Uint8Array): UnitReport {
  if (report.length !== REPORT_LENGTH || report[0] !== 0) {
    throw new ProtocolError('Not a host report.');
  }
  const at = (i: number) => report[i] ?? 0;
  return {
    length: at(1),
    command: at(2),
    seq: at(3),
    parts: at(4),
    part: at(5),
    payload: report.slice(HEADER, HEADER + Math.min(at(6), PART_CAPACITY)),
  };
}

/** The name of a command byte, for logs. */
export function commandName(code: number): string {
  const found = (Object.keys(Command) as CommandName[]).find((name) => Command[name] === code);
  return found ?? `0x${code.toString(16).padStart(2, '0')}`;
}

export const fromHex = (hex: string): Uint8Array =>
  Uint8Array.from(hex.replace(/\s+/g, '').match(/../g) ?? [], (b) => parseInt(b, 16));
export const toHex = (bytes: Uint8Array): string =>
  Array.from(bytes, (b) => b.toString(16).padStart(2, '0')).join('');

