import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import type { Game, Plan, Scheme } from '@helmarray/core';
import { BUILT_IN_DEVICES, gameKeysPreset, resolve } from '@helmarray/core';
import { Command, FakeUnit, parseHostReport } from '@helmarray/azeron';
import { planFingerprint } from './plan-fingerprint';
import { createApplyService } from './apply-service';
import type { ApplyServiceDeps } from './apply-service';
import type { ClosableTransport } from './devices';
import { Devices, POLL_MS } from './devices';
import { verifyUnits } from './apply-units';
import { pendingChanges } from './sync-state';
import { heldUnits } from './app-state';
import { handsFor } from './hands';

const game: Game = {
  id: 'skiff',
  name: 'Skiff',
  modes: [{ id: 'ship', name: 'Ship' }],
  actions: [
    { id: 'boost', name: 'Boost', mode: 'ship', role: 'movement', required: true },
    { id: 'fire', name: 'Fire', mode: 'ship', role: 'combat', required: true },
  ],
  file: { format: 'elite-binds' },
};
const scheme: Scheme = {
  ...gameKeysPreset(game),
  name: 'Main',
  writeGameFile: false,
  // The sticks send nothing here, which the checks call an error until it is accepted.
  accepted: [
    { rule: 'stick-no-directions', control: 'L.stick', reason: 'No stick' },
    { rule: 'stick-no-directions', control: 'R.stick', reason: 'No stick' },
  ],
  map: {
    ship: {
      'L.index_1': { tap: 'boost' },
      'L.middle_1': { tap: 'fire', long: 'boost' },
      'R.index_1': { tap: 'fire' },
    },
  },
};
const plan: Plan = resolve(scheme, game, BUILT_IN_DEVICES);
/** What a preview of the scheme would have given: the layout the person agreed to. */
const fp = (s: Scheme) => planFingerprint(resolve(s, game, BUILT_IN_DEVICES));

const LEFT = 49229;
const RIGHT = 29993;
const HANDS = { [LEFT]: 'left', [RIGHT]: 'right' } as const;

const WRITES: number[] = [
  Command.CHECK_PROFILE,
  Command.PROFILE_NAME,
  Command.OBM_COPY,
  Command.SWITCH_PROFILE,
  Command.DELETE_PROFILE,
];
const writesTo = (unit: FakeUnit) =>
  unit.received.map((r) => parseHostReport(r).command).filter((c) => WRITES.includes(c));

const deferred = () => {
  let release!: () => void;
  const promise = new Promise<void>((resolve) => (release = resolve));
  return { promise, release };
};

/** Two fake units behind a real devices service, and an apply service over them. */
async function rig(
  over: {
    scheme?: Scheme;
    right?: boolean;
    azeron?: () => Promise<boolean>;
    saveApplied?: ApplyServiceDeps['saveApplied'];
    setActive?: ApplyServiceDeps['setActive'];
    saveScheme?: ApplyServiceDeps['saveScheme'];
    trace?: (line: string) => void;
    settled?: () => void | Promise<void>;
  } = {},
) {
  const units = new Map<string, FakeUnit>([
    [
      'left-path',
      new FakeUnit({
        deviceId: LEFT,
        slots: { 0: { name: 'Default' }, 2: { name: 'Old' } },
        running: 0,
      }),
    ],
  ]);
  if (over.right !== false) {
    units.set(
      'right-path',
      new FakeUnit({ deviceId: RIGHT, slots: { 0: { name: 'Default' } }, running: 0 }),
    );
  }
  const bench = { listed: 0, opened: [] as string[], closed: [] as string[] };
  // What the devices service asks: not open while the units connect, then what the test says.
  const look = { fn: (): Promise<boolean> => Promise.resolve(false) };
  const devices = new Devices({
    azeronAppRunning: () => look.fn(),
    findUnits: () => {
      bench.listed++;
      return Promise.resolve([...units.keys()].map((path) => ({ path })));
    },
    openUnit: (path): Promise<ClosableTransport> => {
      bench.opened.push(path);
      const unit = units.get(path);
      if (!unit) return Promise.reject(new Error('nothing there'));
      return Promise.resolve({
        send: (report) => unit.send(report),
        receive: () => unit.receive(),
        close: () => {
          bench.closed.push(path);
          return Promise.resolve();
        },
      });
    },
  });
  devices.start();
  await vi.advanceTimersByTimeAsync(0);

  look.fn = over.azeron ?? (() => Promise.resolve(false));
  const saveApplied = vi.fn(over.saveApplied ?? (() => Promise.resolve()));
  const setActive = vi.fn(over.setActive ?? (() => Promise.resolve()));
  const settled = vi.fn(over.settled);
  // The store, as far as Apply sees it: the scheme as saved, which a save replaces.
  const store = { scheme: over.scheme ?? scheme };
  const saveScheme = vi.fn(
    over.saveScheme ??
      ((next: Scheme) => {
        store.scheme = next;
      }),
  );
  const service = createApplyService({
    plans: {
      getScheme: (id) => Promise.resolve(id === store.scheme.id ? store.scheme : null),
      getGame: (id) => Promise.resolve(id === game.id ? game : undefined),
    },
    devices,
    hands: { get: (id) => HANDS[id as keyof typeof HANDS] },
    azeronAppRunning: (): Promise<boolean> => look.fn(),
    saveApplied,
    setActive,
    saveScheme,
    settled,
    ...(over.trace ? { trace: over.trace } : {}),
  });
  const reports = () => [...units.values()].reduce((n, u) => n + u.received.length, 0);
  return {
    service,
    devices,
    units,
    bench,
    saveApplied,
    setActive,
    saveScheme,
    store,
    settled,
    reports,
    left: units.get('left-path') as FakeUnit,
    right: units.get('right-path'),
  };
}

describe('Apply as the windows ask for it', () => {
  let r: Awaited<ReturnType<typeof rig>> | undefined;
  beforeEach(() => void vi.useFakeTimers());
  afterEach(async () => {
    await r?.devices.stop();
    r = undefined;
    vi.useRealTimers();
  });

  it('previews what is ready and what changes on each unit, writing nothing', async () => {
    r = await rig();
    const before = writesTo(r.left).length;
    const preview = await r.service.preview(scheme.id);
    expect(preview).toMatchObject({
      ready: true,
      schemeName: 'Main',
      gameName: 'Skiff',
      azeronOpen: false,
      busy: false,
      anyChange: true,
    });
    expect(preview.checks.every((c) => c.ok)).toBe(true);
    expect(preview.checks.map((c) => c.text)).toEqual([
      'The Azeron app is closed.',
      'The left Azeron is connected.',
      'The right Azeron is connected.',
      'The scheme has no errors.',
    ]);
    // The lowest free slot, named for the scheme; the others go, by name.
    expect(preview.left.write).toEqual({ slot: 1, name: 'Main', overwrites: null });
    expect(preview.left.deletes).toEqual([
      { slot: 0, name: 'Default' },
      { slot: 2, name: 'Old' },
    ]);
    expect(preview.right.write).toMatchObject({ slot: 1, name: 'Main' });
    expect(structuredClone(preview)).toEqual(preview);
    expect(writesTo(r.left).length).toBe(before);
  });

  it('applies: both units hold the layout, and only then is it remembered and made active', async () => {
    r = await rig();
    const result = await r.service.apply(scheme.id, fp(scheme));
    expect(result.ok).toBe(true);
    expect(result.message).toBe('Both units now run the layout.');
    expect(result.units.map((u) => [u.hand, u.status])).toEqual([
      ['left', 'applied'],
      ['right', 'applied'],
    ]);
    expect(r.saveApplied).toHaveBeenCalledTimes(1);
    expect(r.saveApplied).toHaveBeenCalledWith(scheme.id, plan);
    expect(r.setActive).toHaveBeenCalledWith('skiff', scheme.id);
    expect(r.settled).toHaveBeenCalledTimes(1);

    // The service was read again before the hold was let go: what the pill compares is real.
    const snapshot = r.devices.snapshot();
    const held = heldUnits(snapshot, handsFor([LEFT, RIGHT], { get: (id) => HANDS[id as 49229] }));
    expect(held.left?.slots.map((s) => s.slot)).toEqual([1]);
    expect(held.left?.running).toBe(1);
    const verdicts = verifyUnits(plan, held);
    expect(verdicts.left).toEqual({ differences: [], unchecked: [] });
    expect(verdicts.right).toEqual({ differences: [], unchecked: [] });
    expect(result.units[0]?.slot).toBe(1);
  });

  it('is nothing to do on a second apply of the same scheme, and still remembers it', async () => {
    r = await rig();
    await r.service.apply(scheme.id, fp(scheme));
    const again = await r.service.apply(scheme.id, fp(scheme));
    expect(again).toMatchObject({ ok: true, message: 'Both units already held the layout.' });
    expect(r.saveApplied).toHaveBeenCalledTimes(2);
    expect((await r.service.preview(scheme.id)).anyChange).toBe(false);
  });

  describe('when the Azeron app is open', () => {
    it('says so, looks at no unit, and refuses to write', async () => {
      r = await rig({ azeron: () => Promise.resolve(true) });
      const reports = r.reports();
      const preview = await r.service.preview(scheme.id);
      expect(preview).toMatchObject({ ready: false, azeronOpen: true });
      expect(preview.checks).toEqual(
        expect.arrayContaining([
          { ok: false, text: 'Close the Azeron app first: it talks to the units too.' },
        ]),
      );
      // Not "unplugged": the units were not looked at.
      expect(preview.checks.some((c) => /isn't connected/.test(c.text))).toBe(false);

      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result).toEqual({
        ok: false,
        message: 'Close the Azeron app first: it talks to the units too.',
        units: [],
      });
      expect(r.reports()).toBe(reports);
      expect(r.saveApplied).not.toHaveBeenCalled();
      expect(r.setActive).not.toHaveBeenCalled();
    });

    it('the preview leaves the units alone when the app opens just after its own look', async () => {
      let looks = 0;
      r = await rig({ azeron: () => Promise.resolve(++looks > 1) });
      await vi.advanceTimersByTimeAsync(10_000); // what the service read is old enough to be read again
      looks = 0;
      const reports = r.reports();
      const preview = await r.service.preview(scheme.id);
      expect(r.reports()).toBe(reports);
      expect(preview.ready).toBe(false);
      expect(preview.checks.some((c) => /hasn't been read yet/.test(c.text))).toBe(true);
    });

    it('does not trust a look at the programs that failed', async () => {
      r = await rig({ azeron: () => Promise.reject(new Error('tasklist failed')) });
      const preview = await r.service.preview(scheme.id);
      expect(preview.ready).toBe(false);
      expect(preview.checks[0]?.text).toBe(
        "helmArray couldn't tell whether the Azeron app is open.",
      );
      expect((await r.service.apply(scheme.id, fp(scheme))).ok).toBe(false);
      expect(r.saveApplied).not.toHaveBeenCalled();
    });

    /**
     * One apply with a look that never says open, to find where things fall: how many looks the
     * whole apply made, and the number of the look that came first from the right unit's flow
     * (its own guard, then the gate's look before its first command).
     */
    async function dryRun() {
      const seen: { right: number; at: number }[] = [];
      let total = 0;
      const dry = await rig({
        azeron: () => {
          seen.push({ right: dry.right?.received.length ?? 0, at: ++total });
          return Promise.resolve(false);
        },
      });
      const before = dry.right?.received.length ?? 0;
      await dry.service.apply(scheme.id, fp(scheme));
      const first = seen.find((x) => x.right > before);
      await dry.devices.stop();
      return { total, rightsFirstReport: first?.at ?? total };
    }

    it.each([
      ['at its own check', 2],
      ['at the session look before its first command', 1],
    ])(
      'opening between the units, %s: no unit is sent another command, nothing is remembered',
      async (_which, back) => {
        const { rightsFirstReport } = await dryRun();
        const opens = rightsFirstReport - back;
        let looks = 0;
        let atOpening: number[] | undefined;
        const rigged = await rig({
          azeron: () => {
            const open = ++looks >= opens;
            if (open && !atOpening)
              atOpening = [...rigged.units.values()].map((u) => u.received.length);
            return Promise.resolve(open);
          },
        });
        r = rigged;
        const result = await rigged.service.apply(scheme.id, fp(scheme));
        expect(result.ok).toBe(false);
        expect(result.units.map((u) => u.status)).toEqual(['applied', 'failed']);
        expect(result.message).toMatch(/right unit failed: .*Azeron app/);
        expect(rigged.saveApplied).not.toHaveBeenCalled();
        expect(rigged.setActive).not.toHaveBeenCalled();
        expect(rigged.right && writesTo(rigged.right)).toEqual([]);
        // Not one command to either unit after the Azeron app appeared, the read afterwards included.
        expect(atOpening).toBeDefined();
        expect([...rigged.units.values()].map((u) => u.received.length)).toEqual(atOpening);
        // What the units hold is no longer known, and the pill is not told it is.
        expect(rigged.devices.snapshot().units.map((u) => u.slots)).toEqual([undefined, undefined]);
        expect((await rigged.service.preview(scheme.id)).ready).toBe(false);
      },
    );

    it('does not read the units again after an apply when the app cannot be ruled out', async () => {
      const { total } = await dryRun();
      let looks = 0;
      let atFailure: number[] | undefined;
      const rigged = await rig({
        azeron: () => {
          // Everything of the apply itself looks fine; the looks of the read afterwards fail.
          if (++looks > total - 6) {
            atFailure ??= [...rigged.units.values()].map((u) => u.received.length);
            return Promise.reject(new Error('tasklist failed'));
          }
          return Promise.resolve(false);
        },
      });
      r = rigged;
      const result = await rigged.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(true);
      expect([...rigged.units.values()].map((u) => u.received.length)).toEqual(atFailure);
      expect(rigged.devices.snapshot().units.every((u) => u.slots === undefined)).toBe(true);
    });

    it('reads the units again after a good apply only while the app is still closed, operation by operation', async () => {
      const { total } = await dryRun();
      let looks = 0;
      let atOpening: number[] | undefined;
      const rigged = await rig({
        azeron: () => {
          // The read afterwards makes six looks, three a unit; the app opens at the right unit's first.
          const open = ++looks > total - 3;
          if (open) atOpening ??= [...rigged.units.values()].map((u) => u.received.length);
          return Promise.resolve(open);
        },
      });
      r = rigged;
      const result = await rigged.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(true);
      const [left, right] = rigged.devices.snapshot().units;
      expect(left?.slots?.map((x) => x.slot)).toEqual([1]);
      expect(right?.slots).toBeUndefined();
      expect([...rigged.units.values()].map((u) => u.received.length)).toEqual(atOpening);
    });
  });

  describe('keeping the keys that were dealt', () => {
    const planOf = (s: Scheme) => resolve(s, game, BUILT_IN_DEVICES);
    const keyOf = (p: Plan, control: string) => {
      const pin = [...p.units.left.pins, ...p.units.right.pins].find((x) => x.control === control);
      return JSON.stringify(pin?.presses);
    };

    it('writes the plan ledger into the scheme, and nothing else of it, after a good apply', async () => {
      r = await rig();
      expect(plan.ledger).not.toEqual({});
      expect(scheme.ledger).toEqual({});
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(true);
      expect(r.saveScheme).toHaveBeenCalledTimes(1);
      expect(r.saveScheme).toHaveBeenCalledWith({ ...scheme, ledger: plan.ledger });
      expect(r.store.scheme.ledger).toEqual(plan.ledger);
    });

    it('leaves nothing to apply: the scheme with its ledger resolves to the plan that was applied', async () => {
      r = await rig();
      const before = (await r.service.preview(scheme.id)).fingerprint;
      await r.service.apply(scheme.id, fp(scheme));
      const after = planOf(r.store.scheme);
      expect(planFingerprint(after)).toBe(planFingerprint(plan));
      expect(after).toEqual(plan);
      // So the pill has no change to report, and the next preview is of the same layout.
      expect(pendingChanges(plan, after)).toBe(0);
      expect((await r.service.preview(scheme.id)).fingerprint).toBe(before);
    });

    it('gives a button the key it has, whatever is added on an earlier button afterwards', async () => {
      const two: Scheme = {
        ...scheme,
        map: { ship: { 'L.index_1': { tap: 'boost' }, 'R.index_1': { tap: 'fire' } } },
      };
      const added: Scheme['map'] = {
        ship: { ...two.map['ship'], 'L.middle_1': { tap: 'map' } },
      };
      const withMap: Game = {
        ...game,
        actions: [
          ...game.actions,
          { id: 'map', name: 'Map', mode: 'ship', role: 'menu', required: false },
        ],
      };
      const resolveWith = (s: Scheme) => resolve(s, withMap, BUILT_IN_DEVICES);
      r = await rig({ scheme: two });
      const applied = planOf(two);
      await r.service.apply(two.id, fp(two));

      // Without the ledger in the scheme, an earlier button takes the first key and the others move.
      const moved = resolveWith({ ...two, map: added });
      expect(keyOf(moved, 'L.index_1')).not.toBe(keyOf(applied, 'L.index_1'));
      // With it, the two that were dealt keys keep them, and the new button gets a new one.
      const kept = resolveWith({ ...r.store.scheme, map: added });
      expect(keyOf(kept, 'L.index_1')).toBe(keyOf(applied, 'L.index_1'));
      expect(keyOf(kept, 'R.index_1')).toBe(keyOf(applied, 'R.index_1'));
      expect(keyOf(kept, 'L.middle_1')).not.toBe(keyOf(applied, 'L.index_1'));
      expect(keyOf(kept, 'L.middle_1')).not.toBe(keyOf(applied, 'R.index_1'));
    });

    it('does not touch the scheme when the apply failed, in part or whole, or was refused', async () => {
      let looks = 0;
      r = await rig({ azeron: () => Promise.resolve(++looks === 2) });
      expect((await r.service.apply(scheme.id, fp(scheme))).ok).toBe(false);
      expect((await r.service.apply(scheme.id, 'another layout')).ok).toBe(false);
      expect(r.saveScheme).not.toHaveBeenCalled();
      expect(r.store.scheme.ledger).toEqual({});
    });

    it('writes nothing when the units already held the layout and the scheme already has its keys', async () => {
      r = await rig();
      await r.service.apply(scheme.id, fp(scheme));
      await r.service.apply(scheme.id, fp(scheme));
      expect(r.saveScheme).toHaveBeenCalledTimes(1);
    });

    it('does not write over an edit that landed while it was writing, and says so', async () => {
      const held: { rig?: Awaited<ReturnType<typeof rig>> } = {};
      const edited: Scheme = {
        ...scheme,
        map: { ship: { ...scheme.map['ship'], 'R.index_1': { tap: 'boost' } } },
      };
      r = await rig({
        saveApplied: () => {
          if (held.rig) held.rig.store.scheme = edited;
          return Promise.resolve();
        },
      });
      held.rig = r;
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(false);
      expect(result.message).toMatch(/the scheme was edited meanwhile/);
      expect(r.saveScheme).not.toHaveBeenCalled();
      expect(r.store.scheme).toBe(edited);
    });

    it('says so when the scheme could not be saved, the units being set', async () => {
      r = await rig({ saveScheme: () => Promise.reject(new Error('disk full')) });
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(false);
      expect(result.message).toMatch(
        /keys it was given couldn't be kept in the scheme \(disk full\)/,
      );
      expect(result.units.map((u) => u.status)).toEqual(['applied', 'applied']);
      expect(r.saveApplied).toHaveBeenCalledTimes(1);
    });

    it('keeps the keys even when the note of the apply could not be saved', async () => {
      r = await rig({ saveApplied: () => Promise.reject(new Error('disk full')) });
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(false);
      expect(r.saveScheme).toHaveBeenCalledTimes(1);
    });
  });

  describe('writing exactly what was previewed', () => {
    it('gives a fingerprint with the preview, the same for the same layout and another for another', async () => {
      r = await rig();
      const preview = await r.service.preview(scheme.id);
      expect(preview.fingerprint).toMatch(/^[0-9a-f]{32}$/);
      expect(preview.fingerprint).toBe(fp(scheme));
      expect(fp({ ...scheme, map: { ship: { 'L.index_1': { tap: 'boost' } } } })).not.toBe(
        preview.fingerprint,
      );
      expect((await r.service.preview('nope')).fingerprint).toBe('');
    });

    it('refuses, in one sentence, a layout other than the one previewed, and writes nothing', async () => {
      r = await rig();
      const reports = r.reports();
      const result = await r.service.apply(scheme.id, 'a fingerprint of some other layout');
      expect(result).toEqual({
        ok: false,
        changed: true,
        message: 'The layout changed since the preview: look again.',
        units: [],
      });
      expect(r.reports()).toBe(reports);
      expect(r.saveApplied).not.toHaveBeenCalled();
      expect(r.setActive).not.toHaveBeenCalled();
      expect(r.service.busy()).toBe(false);
    });

    it('refuses a scheme edited after the preview, and applies it after a new preview', async () => {
      let current = scheme;
      r = await rig();
      // The store hands back whatever the scheme is now: an undo under the drawer changes it.
      const live = createApplyService({
        plans: {
          getScheme: () => Promise.resolve(current),
          getGame: () => Promise.resolve(game),
        },
        devices: r.devices,
        hands: { get: (id) => HANDS[id as keyof typeof HANDS] },
        azeronAppRunning: () => Promise.resolve(false),
        saveApplied: r.saveApplied,
        setActive: r.setActive,
        saveScheme: r.saveScheme,
      });
      const seen = await live.preview(scheme.id);
      current = {
        ...scheme,
        map: { ship: { ...scheme.map['ship'], 'L.index_1': { tap: 'fire' } } },
      };
      const stale = await live.apply(scheme.id, seen.fingerprint);
      expect(stale).toMatchObject({ ok: false, changed: true });
      expect(r.saveApplied).not.toHaveBeenCalled();
      const again = await live.preview(scheme.id);
      expect(again.fingerprint).not.toBe(seen.fingerprint);
      expect((await live.apply(scheme.id, again.fingerprint)).ok).toBe(true);
    });
  });

  describe('when a unit is missing', () => {
    it('says which, and refuses to write the other one either', async () => {
      r = await rig({ right: false });
      const preview = await r.service.preview(scheme.id);
      expect(preview.ready).toBe(false);
      expect(preview.checks).toContainEqual({
        ok: false,
        text: "The right Azeron isn't connected.",
      });
      expect(preview.checks).toContainEqual({ ok: true, text: 'The left Azeron is connected.' });
      expect(preview.right.connected).toBe(false);

      const before = writesTo(r.left).length;
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result).toEqual({
        ok: false,
        message: "The right Azeron isn't connected.",
        units: [],
      });
      expect(writesTo(r.left).length).toBe(before);
      expect(r.saveApplied).not.toHaveBeenCalled();
    });
  });

  describe('the scheme itself', () => {
    it('refuses a scheme that is not there, in a sentence', async () => {
      r = await rig();
      expect(await r.service.apply('nope', 'whatever')).toEqual({
        ok: false,
        message: 'There is no such scheme.',
        units: [],
      });
      expect((await r.service.preview('nope')).checks).toEqual([
        { ok: false, text: 'There is no such scheme.' },
      ]);
    });

    const unplaced: Scheme = {
      ...scheme,
      map: { ship: { 'L.index_1': { tap: 'boost' }, 'R.index_1': { tap: 'boost' } } },
    };

    it('blocks on an error the player has not accepted, naming it, and writes nothing', async () => {
      r = await rig({ scheme: unplaced });
      const preview = await r.service.preview(unplaced.id);
      expect(preview.ready).toBe(false);
      expect(preview.checks).toContainEqual({
        ok: false,
        text: 'Fire is needed to play Ship, and it is on no button.',
      });
      const reports = r.reports();
      const result = await r.service.apply(unplaced.id, fp(unplaced));
      expect(result.ok).toBe(false);
      expect(result.message).toBe('Fire is needed to play Ship, and it is on no button.');
      expect(r.saveApplied).not.toHaveBeenCalled();
      expect(r.reports()).toBe(reports);
    });

    it('does not block on an error the player accepted', async () => {
      const accepted: Scheme = {
        ...unplaced,
        accepted: [
          ...scheme.accepted,
          { rule: 'missing-required', action: 'fire', reason: 'Not needed' },
        ],
      };
      r = await rig({ scheme: accepted });
      expect((await r.service.preview(accepted.id)).ready).toBe(true);
      expect((await r.service.apply(accepted.id, fp(accepted))).ok).toBe(true);
    });
  });

  describe('one apply at a time', () => {
    it('refuses a second request while one runs, in a sentence, and the first is unharmed', async () => {
      const gate = deferred();
      let first = true;
      r = await rig({
        azeron: async () => {
          if (first) {
            first = false;
            await gate.promise;
          }
          return false;
        },
      });
      const running = r.service.apply(scheme.id, fp(scheme));
      await vi.advanceTimersByTimeAsync(0);
      expect(r.service.busy()).toBe(true);

      const second = await r.service.apply(scheme.id, fp(scheme));
      expect(second).toEqual({
        ok: false,
        message: 'An apply is already running. Wait for it to finish.',
        units: [],
      });
      const preview = await r.service.preview(scheme.id);
      expect(preview).toMatchObject({ ready: false, busy: true });

      gate.release();
      expect((await running).ok).toBe(true);
      expect(r.saveApplied).toHaveBeenCalledTimes(1);
      expect(r.service.busy()).toBe(false);
    });

    it('two requests in the same moment: one runs, one is refused', async () => {
      r = await rig();
      const [a, b] = await Promise.all([
        r.service.apply(scheme.id, fp(scheme)),
        r.service.apply(scheme.id, fp(scheme)),
      ]);
      expect([a.ok, b.ok].sort()).toEqual([false, true]);
      expect(r.saveApplied).toHaveBeenCalledTimes(1);
    });

    it('is free again after a failed one', async () => {
      let look = 0;
      r = await rig({ azeron: () => Promise.resolve(++look === 2) });
      const failed = await r.service.apply(scheme.id, fp(scheme));
      expect(failed.ok).toBe(false);
      expect(r.service.busy()).toBe(false);
      const next = await r.service.apply(scheme.id, fp(scheme));
      expect(next.ok).toBe(true);
    });

    it('is free again, and the devices service released, after something throws', async () => {
      r = await rig({ saveApplied: () => Promise.reject(new Error('disk full')) });
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(false);
      expect(r.service.busy()).toBe(false);
      const listed = r.bench.listed;
      await vi.advanceTimersByTimeAsync(POLL_MS);
      expect(r.bench.listed).toBeGreaterThan(listed);
    });
  });

  describe('remembering', () => {
    it('says so when the units are set but the note could not be kept, and does not make it active', async () => {
      r = await rig({ saveApplied: () => Promise.reject(new Error('disk full')) });
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(false);
      expect(result.message).toBe(
        "Both units now run the layout, but helmArray couldn't keep a note of it (disk full), so it can't say they are in sync.",
      );
      expect(result.units.map((u) => u.status)).toEqual(['applied', 'applied']);
      expect(r.setActive).not.toHaveBeenCalled();
    });

    it('says so when it could not be made the current scheme', async () => {
      r = await rig({ setActive: () => Promise.reject(new Error('no such game')) });
      const result = await r.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(false);
      expect(result.message).toMatch(/couldn't be made the current scheme \(no such game\)/);
      expect(r.saveApplied).toHaveBeenCalledTimes(1);
    });
  });

  describe('the devices service during an apply', () => {
    it('neither lists, opens, closes nor reads while the units are written', async () => {
      const probes: { listed: number; opened: string[]; closed: string[] }[] = [];
      const held: { rig?: Awaited<ReturnType<typeof rig>> } = {};
      let looks = 0;
      const service = await rig({
        azeron: async () => {
          // The first look is the readiness check, before the units are held.
          if (++looks === 1) return false;
          const bench = held.rig?.bench;
          // Every step of the apply asks this; time passes meanwhile, and a third unit appears.
          held.rig?.units.set('third-path', new FakeUnit({ deviceId: 1234 }));
          await vi.advanceTimersByTimeAsync(POLL_MS * 3);
          if (bench) {
            probes.push({
              listed: bench.listed,
              opened: [...bench.opened],
              closed: [...bench.closed],
            });
          }
          return false;
        },
      });
      held.rig = service;
      r = service;
      const listedBefore = service.bench.listed;
      const result = await service.service.apply(scheme.id, fp(scheme));
      expect(result.ok).toBe(true);
      expect(probes.length).toBeGreaterThan(5);
      for (const probe of probes) {
        expect(probe.listed).toBe(probes[0]?.listed);
        expect(probe.opened).toEqual(['left-path', 'right-path']);
        expect(probe.closed).toEqual([]);
      }
      expect(probes[0]?.listed).toBeGreaterThanOrEqual(listedBefore);
      // Once the apply is over, polling is back and the new unit is found.
      await vi.advanceTimersByTimeAsync(POLL_MS);
      expect(service.bench.opened).toContain('third-path');
    });
  });

  it('survives its units being read for the preview just as the apply wants them', async () => {
    r = await rig();
    const [preview, applied] = await Promise.all([
      r.service.preview(scheme.id),
      r.service.apply(scheme.id, fp(scheme)),
    ]);
    expect(applied.ok).toBe(true);
    expect(preview.schemeName).toBe('Main');
  });
});

describe('Apply says what it did, to the log', () => {
  let r: Awaited<ReturnType<typeof rig>> | undefined;
  beforeEach(() => void vi.useFakeTimers());
  afterEach(async () => {
    await r?.devices.stop();
    r = undefined;
    vi.useRealTimers();
  });

  it('prefixes what the units flow says with apply:, so the log shows whose line it is', async () => {
    const lines: string[] = [];
    r = await rig({ trace: (line) => lines.push(line) });
    await r.service.apply(scheme.id, fp(scheme));
    expect(lines).toContain('apply: left: writing the layout into slot 1');
  });

  it('says when the keys it was dealt were not kept, because the scheme was edited meanwhile', async () => {
    const lines: string[] = [];
    const held: { rig?: Awaited<ReturnType<typeof rig>> } = {};
    const edited: Scheme = {
      ...scheme,
      map: { ship: { ...scheme.map['ship'], 'R.index_1': { tap: 'boost' } } },
    };
    r = await rig({
      trace: (line) => lines.push(line),
      saveApplied: () => {
        if (held.rig) held.rig.store.scheme = edited;
        return Promise.resolve();
      },
    });
    held.rig = r;
    await r.service.apply(scheme.id, fp(scheme));
    expect(lines).toContain(
      "ledger: Both units now run the layout, but the scheme was edited meanwhile, so the keys it was given weren't kept: apply again.",
    );
  });

  it('says nothing of the ledger when the keys were kept', async () => {
    const lines: string[] = [];
    r = await rig({ trace: (line) => lines.push(line) });
    await r.service.apply(scheme.id, fp(scheme));
    expect(lines.filter((line) => line.startsWith('ledger:'))).toEqual([]);
  });

  it('survives what is to run after an apply failing, and says so', async () => {
    const lines: string[] = [];
    r = await rig({
      trace: (line) => lines.push(line),
      settled: () => Promise.reject(new Error('state could not be worked out')),
    });
    const result = await r.service.apply(scheme.id, fp(scheme));
    expect(result.ok).toBe(true);
    expect(lines).toContain('after an apply: state could not be worked out');
  });

  it('survives a log that throws', async () => {
    r = await rig({
      trace: () => {
        throw new Error('the log is full');
      },
    });
    expect((await r.service.apply(scheme.id, fp(scheme))).ok).toBe(true);
  });
});

test/integration/unplug-mid-write.test.t.source:
// The right unit is unplugged while its slot is being written. The result names the unit, nothing
// is recorded as applied, the unit is left part-written but still running what it ran, and once
// it is back a second Apply finishes the job.

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { Command, parseHostReport } from '@helmarray/azeron';
import type { Plan, Scheme } from '@helmarray/core';
import type { ApplyResult } from '../../packages/app/src/shared/api';
import { World, expectedSlot, heldSlot, holding } from './support/world';

/** The record piece after which the cable comes out: part way through the layout. */
const UNPLUGGED_AFTER_PIECE = 3;

describe('the right unit is unplugged mid-write', () => {
  let world: World;
  let scheme: Scheme;
  let plan: Plan;
  let failed: ApplyResult;
  let pieces = 0;

  beforeAll(async () => {
    world = await World.create();
    await world.boot();
    scheme = await world.createKeysScheme();
    plan = await world.planOf(scheme);
    const preview = await world.helm.previewApply(scheme.id);
    world.right.afterFrame((frame) => {
      if (
        parseHostReport(frame).command === Command.OBM_COPY &&
        ++pieces === UNPLUGGED_AFTER_PIECE
      ) {
        world.right.unplug();
      }
    });
    failed = await world.helm.apply(scheme.id, preview.fingerprint);
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('the cable came out while the layout was going in (the moment the test hangs it on happened)', () => {
    expect([pieces, world.right.plugged]).toEqual([UNPLUGGED_AFTER_PIECE, false]);
  });

  it('Apply fails, names the right unit, and says its new slot may be part-written', () => {
    expect([failed.ok, failed.message]).toEqual([
      false,
      expect.stringMatching(
        /^The right unit failed: .+; a new slot 1 may be part-written, and the unit still runs slot 0 with its other slots as they were\.$/,
      ),
    ]);
  });

  it('the left unit had finished and the right one failed', () => {
    expect(failed.units.map((unit) => [unit.hand, unit.status])).toEqual([
      ['left', 'applied'],
      ['right', 'failed'],
    ]);
  });

  it('the right unit still runs slot 0, as it did', () => {
    expect(holding(world.right).running).toBe(0);
  });

  it('the right unit holds the first record of the layout in slot 1, of 31', () => {
    expect({
      held: Object.keys(heldSlot(world.right, 1) ?? {}),
      whole: Object.keys(expectedSlot(plan, 'right', 1)).length,
    }).toEqual({ held: ['1'], whole: 31 });
  });

  it('nothing is recorded as applied', async () => {
    expect(await world.app.data.getApplied(scheme.id)).toBeNull();
  });

  it('the scheme is not made the active one', () => {
    expect(world.state.activeSchemeId).toBeNull();
  });

  describe('then the unit is plugged back in', () => {
    let second: ApplyResult;

    beforeAll(async () => {
      // The service notices the unit gone at its next poll, as it would a second later...
      await world.until('the unplugged unit to be let go', () => world.state.devices.length === 1);
      world.right.replug();
      // ...and finds it again at a poll after the cable is back.
      await world.waitForBothUnits();
      const preview = await world.helm.previewApply(scheme.id);
      second = await world.helm.apply(scheme.id, preview.fingerprint);
    });

    it('the second Apply says both units run the layout', () => {
      expect(second.message).toBe('Both units now run the layout.');
    });

    it('the left unit, which already held it, is left alone', () => {
      expect(second.units.map((unit) => [unit.hand, unit.status])).toEqual([
        ['left', 'unchanged'],
        ['right', 'applied'],
      ]);
    });

    it('the right unit holds the layout in a fresh slot 2, runs it, and nothing else is left', () => {
      expect({ ...holding(world.right), records: heldSlot(world.right, 2) }).toEqual({
        slots: { 2: "Game's own keys" },
        running: 2,
        records: expectedSlot(plan, 'right', 2),
      });
    });

    it('the store now holds the plan as applied', async () => {
      expect(await world.app.data.getApplied(scheme.id)).toEqual(plan);
    });

    it('the pill reads In sync', () => {
      expect(world.state.sync).toEqual({ label: 'In sync', tone: 'ok' });
    });
  });
});

test/integration/hands.test.ts.source:
// Which unit is which hand. `hands.json` holds unit id to hand; the coordinator shows it on the
// chips, and Apply writes each half of the layout to the unit that is that hand. A unit with no
// saved hand is asked about, and the first of the two unplugged is the left one.

import { afterEach, describe, expect, it } from 'vitest';
import type { Hand } from '@helmarray/core';
import { World, LEFT_ID, RIGHT_ID, expectedSlot, heldSlot } from './support/world';

describe('hands.json', () => {
  const started: World[] = [];
  afterEach(async () => {
    await Promise.all(started.splice(0).map((world) => world.dispose()));
  });

  /** The app, started over a folder whose `hands.json` says `hands`. */
  const start = async (hands: Record<number, Hand> | null | 'unreadable'): Promise<World> => {
    const world = await World.create({ hands });
    started.push(world);
    await world.boot();
    return world;
  };

  it('puts the saved left id on the left chip and the saved right id on the right chip', async () => {
    const world = await start({ [LEFT_ID]: 'left', [RIGHT_ID]: 'right' });
    expect(world.state.devices.map((chip) => [chip.hand, chip.unitId])).toEqual([
      ['left', LEFT_ID],
      ['right', RIGHT_ID],
    ]);
  });

  it('puts the ids the other way round when the file says so', async () => {
    const world = await start({ [LEFT_ID]: 'right', [RIGHT_ID]: 'left' });
    expect(world.state.devices.map((chip) => [chip.hand, chip.unitId])).toEqual([
      ['left', RIGHT_ID],
      ['right', LEFT_ID],
    ]);
  });

  it('writes the left half of a layout to the unit saved as left, even when that is the second one', async () => {
    const world = await start({ [LEFT_ID]: 'right', [RIGHT_ID]: 'left' });
    const scheme = await world.createKeysScheme();
    const plan = await world.planOf(scheme);
    // The two halves are different layouts, or a half on the wrong unit would not show.
    expect(expectedSlot(plan, 'left', 1)).not.toEqual(expectedSlot(plan, 'right', 1));
    await world.previewAndApply(scheme.id);
    expect([heldSlot(world.right, 1), heldSlot(world.left, 1)]).toEqual([
      expectedSlot(plan, 'left', 1),
      expectedSlot(plan, 'right', 1),
    ]);
  });

  it('with only one unit saved, the other is the opposite hand and is saved too', async () => {
    const world = await start({ [RIGHT_ID]: 'right' });
    expect(await world.savedHands()).toEqual({ [LEFT_ID]: 'left', [RIGHT_ID]: 'right' });
  });

  it('with only one unit saved, the other one is shown as that opposite hand', async () => {
    const world = await start({ [RIGHT_ID]: 'right' });
    expect(world.state.devices.map((chip) => [chip.hand, chip.unitId])).toEqual([
      ['left', LEFT_ID],
      ['right', RIGHT_ID],
    ]);
  });

  it('with nothing saved, neither unit has a hand and the question is to unplug the left one', async () => {
    const world = await start(null);
    expect([world.state.devices.map((chip) => chip.hand), world.state.question?.kind]).toEqual([
      ['unknown', 'unknown'],
      'press',
    ]);
  });

  it('with nothing saved, the drawer says helmArray does not know which is the left one', async () => {
    const world = await start(null);
    const scheme = await world.createKeysScheme();
    const preview = await world.helm.previewApply(scheme.id);
    expect(preview.checks.filter((check) => !check.ok).map((check) => check.text)).toEqual([
      "helmArray doesn't know yet which Azeron is the left one.",
      "helmArray doesn't know yet which Azeron is the right one.",
    ]);
  });

  it('with nothing saved, the unit unplugged for the question is the left one, and the file says so', async () => {
    const world = await start(null);
    // The unit with the right id is the one the owner unplugs, so the order of the ids and the
    // order of the units cannot be what decides it.
    world.right.unplug();
    // The unit left behind is told it is the right one once both hands are saved.
    await world.until('the unit left behind to be the right hand', () =>
      world.state.devices.every((chip) => chip.hand === 'right'),
    );
    expect(await world.savedHands()).toEqual({ [RIGHT_ID]: 'left', [LEFT_ID]: 'right' });
  });

  it('that cannot be read does not stop the app: the units are asked about again', async () => {
    const world = await start('unreadable');
    expect([world.state.devices.map((chip) => chip.hand), world.state.question?.kind]).toEqual([
      ['unknown', 'unknown'],
      'press',
    ]);
  });

  it('that cannot be read is said in the log', async () => {
    const world = await start('unreadable');
    const lines = await world.logLines();
    expect(
      lines.filter((line) => line.includes("[(app)] the saved hands couldn't be read")),
    ).toHaveLength(1);
  });
});

test/integration/running-slot.test.ts.source:
// The profile button on a unit moves the slot it runs without a word. The devices service asks
// each unit which slot it runs every few seconds; what it hears reaches the pill, which stops
// saying In sync. The pill is read from the units, never from what the app last did.

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { isWrite } from './support/fake-hid';
import { World, expectedSlot, heldSlot } from './support/world';
import type { Plan } from '@helmarray/core';

describe('the profile button moves the slot the left unit runs', () => {
  let world: World;
  let plan: Plan;
  let framesBeforeTick: { left: number; right: number };

  beforeAll(async () => {
    world = await World.create();
    await world.boot();
    const scheme = await world.createKeysScheme();
    plan = await world.planOf(scheme);
    await world.previewAndApply(scheme.id);
    // Both units hold the layout, run it, and the pill says so: the test starts from there.
    expect([world.state.sync.label, world.state.devices.map((chip) => chip.running)]).toEqual([
      'In sync',
      [1, 1],
    ]);
    // The owner added a spare profile on the left unit (in the Azeron app, earlier) and now
    // presses the unit's profile button: it runs slot 0 and says nothing.
    world.left.unit.slots.set(0, { name: 'Spare', records: new Map() });
    world.left.unit.running = 0;
    framesBeforeTick = {
      left: world.left.unit.received.length,
      right: world.right.unit.received.length,
    };
    await world.runningSlotTick();
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('the tick asked the left unit which slot it runs', () => {
    expect(world.left.unit.received.length).toBeGreaterThan(framesBeforeTick.left);
  });

  it('the left chip shows slot 0 as the one it runs', () => {
    expect(world.state.devices.map((chip) => [chip.hand, chip.running])).toEqual([
      ['left', 0],
      ['right', 1],
    ]);
  });

  it('the pill says the left unit differs, and not In sync', () => {
    expect(world.state.sync).toEqual({
      label: 'Left unit differs',
      tone: 'error',
      detail: expect.stringMatching(/^Left unit: \d+ inputs? not as applied\.$/),
    });
  });

  it('asking is not writing: nothing but questions reached the left unit', () => {
    expect(world.left.commands().slice(framesBeforeTick.left).filter(isWrite)).toEqual([]);
  });

  it('the layout is still in slot 1 on the left unit: only what runs changed', () => {
    expect(heldSlot(world.left, 1)).toEqual(expectedSlot(plan, 'left', 1));
  });

  it('pressing the button back to the layout puts the pill back to In sync', async () => {
    world.left.unit.running = 1;
    await world.runningSlotTick();
    expect(world.state.sync).toEqual({ label: 'In sync', tone: 'ok' });
  });
});

test/integration/j1-apply.test.ts.source:
// J1 end to end: a scheme from the Xbox controller preset on Helldivers 2 is previewed, applied
// and verified, through `window.helm`, over the real services and a fake pair of units.

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { ApplyPreview, ApplyResult } from '../../packages/app/src/shared/api';
import type { Plan, Scheme } from '@helmarray/core';
import { isWrite } from './support/fake-hid';
import { HELLDIVERS2, World, expectedSlot, heldSlot, holding } from './support/world';

describe('J1: the Xbox controller preset on Helldivers 2, applied', () => {
  let world: World;
  let scheme: Scheme;
  let plan: Plan;
  let preview: ApplyPreview;
  let result: ApplyResult;

  // One Apply, then each test reads a different thing it left behind.
  beforeAll(async () => {
    world = await World.create();
    await world.boot();
    // The two units start as stock: one slot, "Default", running. The test depends on that.
    expect([holding(world.left), holding(world.right)]).toEqual([
      { slots: { 0: 'Default' }, running: 0 },
      { slots: { 0: 'Default' }, running: 0 },
    ]);
    const created = await world.createScheme('xbox');
    scheme = await world.keepFindings(created.id);
    plan = await world.planOf(scheme);
    // The two halves of the plan are different layouts: a half on the wrong unit would show.
    expect(expectedSlot(plan, 'left', 1)).not.toEqual(expectedSlot(plan, 'right', 1));
    ({ preview, result } = await world.previewAndApply(scheme.id));
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('the preview was ready and promised a new slot 1 on each unit', () => {
    expect([preview.ready, preview.left.write?.slot, preview.right.write?.slot]).toEqual([
      true,
      1,
      1,
    ]);
  });

  it('Apply says both units run the layout', () => {
    expect(result).toEqual({
      ok: true,
      message: 'Both units now run the layout.',
      units: [
        { hand: 'left', status: 'applied', message: expect.any(String), slot: 1 },
        { hand: 'right', status: 'applied', message: expect.any(String), slot: 1 },
      ],
    });
  });

  it('the left unit holds the plan’s left half in slot 1, named for the scheme, and runs it', () => {
    expect({ ...holding(world.left), records: heldSlot(world.left, 1) }).toEqual({
      slots: { 1: 'Xbox controller' },
      running: 1,
      records: expectedSlot(plan, 'left', 1),
    });
  });

  it('the right unit holds the plan’s right half in slot 1, named for the scheme, and runs it', () => {
    expect({ ...holding(world.right), records: heldSlot(world.right, 1) }).toEqual({
      slots: { 1: 'Xbox controller' },
      running: 1,
      records: expectedSlot(plan, 'right', 1),
    });
  });

  it('the store holds the plan that was applied', async () => {
    expect(await world.app.data.getApplied(scheme.id)).toEqual(plan);
  });

  it('the store holds the scheme with no keys dealt: pad output sends pad controls, not keys', async () => {
    expect([plan.ledger, (await world.scheme(scheme.id)).ledger]).toEqual([{}, {}]);
  });

  it('the scheme is now the game’s active one', () => {
    expect([world.state.activeGameId, world.state.activeSchemeId]).toEqual([
      HELLDIVERS2,
      scheme.id,
    ]);
  });

  it('the sync pill reads In sync', () => {
    expect(world.state.sync).toEqual({ label: 'In sync', tone: 'ok' });
  });
});

describe('J1: a scheme whose errors were not kept', () => {
  let world: World;

  beforeAll(async () => {
    world = await World.create();
    await world.boot();
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('is not ready to apply, and the drawer says why in the game’s words', async () => {
    const fresh = await world.createScheme('xbox');
    const preview = await world.helm.previewApply(fresh.id);
    expect(preview.checks.filter((check) => !check.ok).map((check) => check.text)).toEqual([
      'Move forward is needed to play Default, and it is on no button.',
      'Move back is needed to play Default, and it is on no button.',
      'Strafe left is needed to play Default, and it is on no button.',
      'Strafe right is needed to play Default, and it is on no button.',
      'Fire is needed to play Default, and it is on no button.',
      'Stratagem (hold) is needed to play Default, and it is on no button.',
    ]);
  });

  it('is refused by Apply itself, whatever the drawer showed', async () => {
    const fresh = await world.createScheme('xbox');
    const preview = await world.helm.previewApply(fresh.id);
    const result = await world.helm.apply(fresh.id, preview.fingerprint);
    expect([result.ok, result.units]).toEqual([false, []]);
  });

  it('writes nothing to either unit when Apply is pressed on it, though both were read', async () => {
    const fresh = await world.createScheme('xbox');
    const preview = await world.helm.previewApply(fresh.id);
    await world.helm.apply(fresh.id, preview.fingerprint);
    const sent = [world.left, world.right].map((unit) => unit.commands());
    expect(sent.map((commands) => [commands.length > 0, commands.filter(isWrite)])).toEqual([
      [true, []],
      [true, []],
    ]);
  });
});

test/integration/azeron-app-open.test.ts.source:
// The Azeron app opens while helmArray is idle, and closes again. The watcher of the running
// programs tells the coordinator, which tells the gate, which stops the devices service and lets
// every unit go; Apply, asked in the meantime, refuses in one sentence. When the Azeron app closes
// the units are found and read again.

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import type { ApplyPreview, ApplyResult } from '../../packages/app/src/shared/api';
import { World } from './support/world';

const SENTENCE = 'Close the Azeron app first: it talks to the units too.';

describe('the Azeron app opens while helmArray is idle', () => {
  let world: World;
  let schemeId: string;
  let result: ApplyResult;
  let framesAtOpen: number;
  let opensBefore: number;

  beforeAll(async () => {
    world = await World.create();
    await world.boot();
    schemeId = (await world.createKeysScheme()).id;
    opensBefore = world.hid.opened().length;
    expect(opensBefore).toBe(2);
    framesAtOpen = world.left.unit.received.length + world.right.unit.received.length;
    await world.setAzeronApp(true);
    await world.until('the units to be let go', () => world.state.devices.length === 0);
    const preview = await world.helm.previewApply(schemeId);
    result = await world.helm.apply(schemeId, preview.fingerprint);
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('tells the windows why writing is blocked, in one sentence', () => {
    expect(world.state.writeBlock).toBe(SENTENCE);
  });

  it('lets go of both units: every device opened was closed', () => {
    const closed = world.hid.events.filter((event) => event.op === 'close').length;
    expect(closed).toBe(opensBefore);
  });

  it('refuses Apply with the same sentence, and attempts no unit', () => {
    expect(result).toEqual({ ok: false, message: SENTENCE, units: [] });
  });

  it('sends the units nothing from the moment it opened, the preview and Apply included', () => {
    expect(world.left.unit.received.length + world.right.unit.received.length).toBe(framesAtOpen);
  });

  describe('and closes again', () => {
    beforeAll(async () => {
      await world.setAzeronApp(false);
      await world.waitForBothUnits();
    });

    it('finds and reads both units again', () => {
      expect(world.state.devices.map((chip) => [chip.hand, chip.state, chip.read])).toEqual([
        ['left', 'ready', true],
        ['right', 'ready', true],
      ]);
    });

    it('stops saying writing is blocked', () => {
      expect(world.state.writeBlock).toBeNull();
    });

    it('lets Apply through', async () => {
      const preview = await world.helm.previewApply(schemeId);
      expect((await world.helm.apply(schemeId, preview.fingerprint)).ok).toBe(true);
    });
  });
});

describe('the running programs cannot be listed', () => {
  let world: World;
  let framesBefore: number;
  let preview: ApplyPreview;
  let result: ApplyResult;

  beforeAll(async () => {
    world = await World.create();
    await world.boot();
    const scheme = await world.createKeysScheme();
    framesBefore = world.left.unit.received.length + world.right.unit.received.length;
    world.processes.failing = true;
    preview = await world.helm.previewApply(scheme.id);
    result = await world.helm.apply(scheme.id, preview.fingerprint);
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('the drawer says helmArray cannot tell whether the Azeron app is open, and is not ready', () => {
    expect([
      preview.ready,
      preview.checks.filter((check) => !check.ok).map((check) => check.text),
    ]).toEqual([false, ["helmArray couldn't tell whether the Azeron app is open."]]);
  });

  it('Apply refuses with the same sentence', () => {
    expect(result).toEqual({
      ok: false,
      message: "helmArray couldn't tell whether the Azeron app is open.",
      units: [],
    });
  });

  it('the units are sent nothing while that is so', () => {
    expect(world.left.unit.received.length + world.right.unit.received.length).toBe(framesBefore);
  });

  it('the log says the look failed', async () => {
    const lines = await world.logLines();
    expect(lines.some((line) => line.includes("couldn't look for the Azeron app"))).toBe(true);
  });
});

test/integration/non-azeron-hid.test.ts.source:
// The rudder pedals, an Xbox controller and a unit's other interfaces are on the HID bus the whole
// time. The app asks the bus for the units' ids and nothing else, opens only the units'
// configuration interfaces, and never sends anything that could be a GET_REPORT: that hung the
// pedals until they were replugged. All of it is read at the fake bus.

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { findUnits, openUnit } from '../../packages/app/src/main/hid-transport';
import { FakeHid, PEDALS, XBOX_PAD } from './support/fake-hid';
import { World } from './support/world';

describe('the pedals and other HID devices on the bus during a whole Apply', () => {
  let world: World;

  beforeAll(async () => {
    world = await World.create();
    await world.boot();
    const scheme = await world.createKeysScheme();
    const { result } = await world.previewAndApply(scheme.id);
    // A full run of the app: both units found, read, written and read back.
    expect(result.ok).toBe(true);
    await world.runningSlotTick();
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('the bus was asked for the units’ ids and no others', () => {
    expect([...new Set(world.hid.enumerated())]).toEqual(['16d0:12f7']);
  });

  it('only the two configuration interfaces were ever opened', () => {
    expect([...new Set(world.hid.opened())].sort()).toEqual(
      [world.left.path, world.right.path].sort(),
    );
  });

  it('the pedals were never opened, written, read or closed', () => {
    expect(world.pedals.touched).toEqual([]);
  });

  it('the Xbox controller was never opened, written, read or closed', () => {
    expect(world.xboxPad.touched).toEqual([]);
  });

  it('no GET_REPORT, and no feature report of any kind, reached any device', () => {
    expect(world.hid.forbidden()).toEqual([]);
  });

  it('every write to a unit was one whole frame behind report id 0', () => {
    const sizes = world.hid.events.flatMap((event) => (event.op === 'write' ? [event.bytes] : []));
    expect([sizes.length > 0, [...new Set(sizes)]]).toEqual([true, [65]]);
  });
});

// The fake bus has to be able to see what the tests above say it did not see: a bus that records
// nothing would pass them all.
describe('the fake bus notices what the tests above are about', () => {
  const bus = () => {
    const hid = new FakeHid();
    const unit = hid.plugUnit({ serial: 'x', deviceId: 1 });
    const pedals = hid.plugBystander('The rudder pedals', PEDALS.vendorId, PEDALS.productId, 1);
    const pad = hid.plugBystander('The Xbox controller', XBOX_PAD.vendorId, XBOX_PAD.productId, 1);
    return { hid, unit, pedals, pad };
  };

  it('lists the pedals and the controller when asked for them', async () => {
    const { hid, pedals, pad } = bus();
    expect([
      await hid.enumerate(PEDALS.vendorId, PEDALS.productId),
      await hid.enumerate(XBOX_PAD.vendorId, XBOX_PAD.productId),
    ]).toEqual([[pedals.info], [pad.info]]);
  });

  it('records an unfiltered listing, which would hand the app the pedals', async () => {
    const { hid } = bus();
    await hid.enumerate(0, 0);
    expect(hid.enumerated()).toEqual(['0000:0000']);
  });

  it('records a GET_REPORT on a unit, and refuses it', async () => {
    const { hid, unit } = bus();
    const device = await hid.open(unit.path);
    await expect(device.getFeatureReport(0, 64)).rejects.toThrow(
      'A GET_REPORT must never be sent.',
    );
    expect(hid.forbidden()).toEqual([{ op: 'GET_REPORT', path: unit.path }]);
  });

  it('records the pedals being opened and written to', async () => {
    const { hid, pedals } = bus();
    const device = await hid.open(pedals.info.path ?? '');
    await expect(device.write(new Uint8Array(65))).rejects.toThrow('must never be talked to');
    expect([hid.opened(), pedals.touched]).toEqual([[pedals.info.path], ['open', 'write']]);
  });

  it('the transport refuses to open the pedals, so the app never gets that far', async () => {
    const { hid, pedals } = bus();
    await expect(openUnit(hid, pedals.info.path ?? '')).rejects.toThrow(
      'That is not an Azeron unit’s configuration interface.',
    );
    expect(hid.opened()).toEqual([]);
  });

  it('the transport refuses a unit’s other interfaces', async () => {
    const { hid, unit } = bus();
    await expect(openUnit(hid, unit.otherPaths[0] ?? '')).rejects.toThrow(
      'That is not an Azeron unit’s configuration interface.',
    );
    expect(hid.opened()).toEqual([]);
  });

  it('the transport finds a unit by its configuration interface alone', async () => {
    const { hid, unit } = bus();
    expect(await findUnits(hid)).toEqual([{ path: unit.path }]);
  });
});

test/integration/stale-preview.test.ts.source:
// The drawer was opened, then the scheme was edited, then Apply was pressed with what the drawer
// had shown. The person agreed to the layout they saw, not to another: Apply refuses, writes
// nothing, and says to look again.

import { afterAll, beforeAll, describe, expect, it } from 'vitest';
import { assign } from '../../packages/app/src/renderer/screens/editor-model';
import type { ApplyPreview, ApplyResult } from '../../packages/app/src/shared/api';
import { isWrite } from './support/fake-hid';
import { World, holding } from './support/world';

describe('a preview that is stale when Apply is pressed', () => {
  let world: World;
  let schemeId: string;
  let shown: ApplyPreview;
  let shownAgain: ApplyPreview;
  let result: ApplyResult;

  beforeAll(async () => {
    world = await World.create();
    await world.boot();
    const scheme = await world.createKeysScheme();
    schemeId = scheme.id;
    shown = await world.helm.previewApply(schemeId);
    // Something else is put on a button after the drawer opened.
    await world.edit(schemeId, (current, game) =>
      assign(current, { mode: 'default', control: 'R.index_3', press: 'tap' }, 'reload', game),
    );
    shownAgain = await world.helm.previewApply(schemeId);
    result = await world.helm.apply(schemeId, shown.fingerprint);
  });

  afterAll(async () => {
    await world.dispose();
  });

  it('the edit changed what the preview stands for', () => {
    expect(shownAgain.fingerprint).not.toBe(shown.fingerprint);
  });

  it('Apply refuses, says the layout changed, and attempted no unit', () => {
    expect(result).toEqual({
      ok: false,
      changed: true,
      message: 'The layout changed since the preview: look again.',
      units: [],
    });
  });

  it('no write reached either unit', () => {
    expect([world.left, world.right].map((unit) => unit.commands().filter(isWrite))).toEqual([
      [],
      [],
    ]);
  });

  it('both units still hold only their stock slot', () => {
    expect([holding(world.left), holding(world.right)]).toEqual([
      { slots: { 0: 'Default' }, running: 0 },
      { slots: { 0: 'Default' }, running: 0 },
    ]);
  });

  it('nothing is recorded as applied', async () => {
    expect(await world.app.data.getApplied(schemeId)).toBeNull();
  });

  it('pressing Apply with the fingerprint of the new preview goes through', async () => {
    const second = await world.helm.apply(schemeId, shownAgain.fingerprint);
    expect(second.ok).toBe(true);
  });
});

packages/app/src/main/apply-units.test.t.source:
import { describe, expect, it } from 'vitest';
import type { Game, Hand, Plan, Scheme } from '@helmarray/core';
import { BUILT_IN_DEVICES, gameKeysPreset, resolve } from '@helmarray/core';
import {
  Command,
  FakeUnit,
  UnitError,
  UnitSession,
  encodeRecord,
  parseHostReport,
  storedFromWritten,
  unitRecords,
  verify,
} from '@helmarray/azeron';
import type { StoredSlot, UnitRecord } from '@helmarray/azeron';
import { CYBORG2_LEFT, CYBORG2_RIGHT } from '@helmarray/core';
import type { UnitOps } from './gated-session';
import type { HeldUnit, HeldUnits, UnitsDeps } from './apply-units';
import { applyUnits, chooseSlot, previewUnits, unitSlotName, verifyUnits } from './apply-units';

// Both units are written from one plan: keys from the pool, a long press, a latch, a turbo.
const game: Game = {
  id: 'skiff',
  name: 'Skiff',
  modes: [{ id: 'ship', name: 'Ship' }],
  actions: [
    { id: 'boost', name: 'Boost', mode: 'ship', role: 'movement', required: true },
    { id: 'fire', name: 'Fire', mode: 'ship', role: 'combat', required: true },
    { id: 'map', name: 'Map', mode: 'ship', role: 'menu', required: false },
    { id: 'brake', name: 'Brake', mode: 'ship', role: 'movement', required: false },
  ],
  file: { format: 'elite-binds' },
};
const scheme: Scheme = {
  ...gameKeysPreset(game),
  writeGameFile: false,
  map: {
    ship: {
      'L.index_1': { tap: 'boost' },
      'L.middle_1': { tap: 'fire', long: 'map' },
      'R.index_1': { tap: 'brake' },
      'R.middle_1': { tap: 'fire', long: 'map' },
    },
  },
  behaviour: { 'L.index_1': { latch: true }, 'R.middle_1': { turbo: { interval: 40 } } },
};
const plan: Plan = resolve(scheme, game, BUILT_IN_DEVICES);
const records: Record<Hand, UnitRecord[]> = {
  left: unitRecords(plan.units.left, CYBORG2_LEFT),
  right: unitRecords(plan.units.right, CYBORG2_RIGHT),
};

const LEFT_ID = 49229; // what a FakeUnit says unless told otherwise
const RIGHT_ID = 29993;
const NAME = 'Skiff';

const WRITES: number[] = [
  Command.CHECK_PROFILE,
  Command.PROFILE_NAME,
  Command.OBM_COPY,
  Command.SWITCH_PROFILE,
  Command.DELETE_PROFILE,
];
const sent = (unit: FakeUnit) => unit.received.map((r) => parseHostReport(r).command);
const writesTo = (unit: FakeUnit) => sent(unit).filter((c) => WRITES.includes(c));
const slotsOf = (unit: FakeUnit) => [...unit.slots.keys()].sort((a, b) => a - b);
/** A slot as a unit holds it once the layout is in: every record, in the unit's own layout. */
const holding = (slot: number, hand: Hand) =>
  records[hand].map((r) => storedFromWritten(encodeRecord(slot, r)));

const STICKS = [4, 0x15, 0x28];
const must = <T>(value: T | undefined): T => {
  if (value === undefined) throw new Error('expected a value');
  return value;
};
/** Takes the first button record's tap key off by one, as a unit that stored wrong. */
function flipOneKey(stored: Uint8Array[]) {
  const record = must(stored.find((r) => !STICKS.includes(r[4] ?? 0)));
  record[7] = (record[7] ?? 0) ^ 1;
}

/**
 * Stores one record wrong in a slot, once, after the first record of a write has gone in: the
 * next read of the slots shows it, as a unit that kept something other than it was sent would.
 */
class CorruptingUnit extends FakeUnit {
  corruptSlot: number | undefined;
  private armed = false;
  override async send(report: Uint8Array): Promise<void> {
    const { command } = parseHostReport(report);
    if (command === Command.OBM_COPY) this.armed = true;
    if (command === Command.PROFILE_PAYLOAD_V2 && this.armed) this.corrupt();
    return super.send(report);
  }
  private corrupt() {
    const slot = this.corruptSlot === undefined ? undefined : this.slots.get(this.corruptSlot);
    const record = [...(slot?.records.values() ?? [])].find((r) => !STICKS.includes(r[4] ?? 0));
    if (!record) return;
    record[7] = (record[7] ?? 0) ^ 1;
    this.armed = false;
  }
}

/** The profile button is pressed at a chosen moment: the running slot moves with no command. */
class MovingUnit extends FakeUnit {
  /** Moves to this slot when the next stream of the slots is asked for. */
  moveOnRead: number | undefined;
  override async send(report: Uint8Array): Promise<void> {
    if (
      parseHostReport(report).command === Command.PROFILE_PAYLOAD_V2 &&
      this.moveOnRead !== undefined
    ) {
      this.running = this.moveOnRead;
      this.moveOnRead = undefined;
    }
    return super.send(report);
  }
}

/** Says it runs a slot it does not have once a slot has been deleted. */
class DriftingUnit extends FakeUnit {
  override async send(report: Uint8Array): Promise<void> {
    await super.send(report);
    if (parseHostReport(report).command === Command.DELETE_PROFILE) this.running = 7;
  }
}

interface Rig {
  left: FakeUnit;
  right: FakeUnit;
  deps: UnitsDeps;
  held(): Promise<HeldUnits>;
  azeronCalls: number;
}

/** Two sessions over fake units, read as the devices service reads them on connect. */
async function rig(
  left: FakeUnit,
  right: FakeUnit,
  over: Partial<UnitsDeps> & { ids?: Partial<Record<Hand, number>> } = {},
): Promise<Rig> {
  const sessions = { left: new UnitSession(left), right: new UnitSession(right) };
  const ids = { left: LEFT_ID, right: RIGHT_ID, ...over.ids };
  for (const session of Object.values(sessions)) {
    await session.identify();
    await session.readSlots();
  }
  const state: Rig = {
    left,
    right,
    azeronCalls: 0,
    held: async () => {
      const one = async (hand: Hand): Promise<HeldUnit> => {
        const session = sessions[hand];
        const identity = await session.identify();
        return {
          deviceId: identity.deviceId,
          slots: await session.readSlots(),
          running: await session.runningSlot(),
          slotLimit: identity.slotLimit,
        };
      };
      return { left: await one('left'), right: await one('right') };
    },
    deps: {
      azeronAppRunning: () => {
        state.azeronCalls++;
        return Promise.resolve(false);
      },
      unit: (hand) => ({ session: sessions[hand], deviceId: ids[hand] }),
      name: NAME,
      ...over,
    },
  };
  // `ids` is only for the rig.
  delete (state.deps as { ids?: unknown }).ids;
  return state;
}

const twoUnits = (
  leftOptions: ConstructorParameters<typeof FakeUnit>[0] = {},
  rightOptions: ConstructorParameters<typeof FakeUnit>[0] = {},
) =>
  [
    new FakeUnit({ deviceId: LEFT_ID, chatterEvery: 3, ...leftOptions }),
    new FakeUnit({ deviceId: RIGHT_ID, chatterEvery: 3, ...rightOptions }),
  ] as const;

async function readBack(unit: FakeUnit, hand: Hand) {
  const session = new UnitSession(unit);
  await session.identify();
  const slots = await session.readSlots();
  const running = await session.runningSlot();
  return {
    slots,
    running,
    verdict: verify(records[hand], slots.find((s) => s.slot === running)?.records ?? []),
  };
}

describe('applying to the units', () => {
  it('writes, reads back, switches and deletes the rest: one slot left, running and verified', async () => {
    const [left, right] = twoUnits(
      { slots: { 0: { name: 'Default' }, 2: { name: 'Old' } }, running: 0 },
      { slots: { 0: { name: 'Default' }, 1: { name: 'Mine' }, 3: { name: 'Other' } }, running: 1 },
    );
    const { deps } = await rig(left, right);
    const result = await applyUnits(plan, deps);

    expect(result.ok).toBe(true);
    expect(result.message).toBe('Both units now run the layout.');
    expect(result.units.map((u) => [u.hand, u.status])).toEqual([
      ['left', 'applied'],
      ['right', 'applied'],
    ]);
    // The lowest free slot, so the running one was never written over.
    expect(result.units[0]).toMatchObject({ slot: 1, wrote: true, switched: true });
    expect(result.units[0]?.deleted).toEqual([
      { slot: 0, name: 'Default' },
      { slot: 2, name: 'Old' },
    ]);
    expect(result.units[1]).toMatchObject({ slot: 2 });
    expect(result.units[1]?.verdict).toEqual({ differences: [], unchecked: [] });

    for (const [unit, hand] of [
      [left, 'left'],
      [right, 'right'],
    ] as const) {
      const after = await readBack(unit, hand);
      expect(after.slots.map((s) => [s.slot, s.name])).toEqual([[unit === left ? 1 : 2, NAME]]);
      expect(after.running).toBe(after.slots[0]?.slot);
      expect(after.verdict).toEqual({ differences: [], unchecked: [] });
    }
  });

  it('does things in the order the unit needs: write, then switch, then delete', async () => {
    const [left, right] = twoUnits({ slots: { 0: { name: 'Default' }, 2: { name: 'Old' } } });
    const { deps } = await rig(left, right);
    await applyUnits(plan, deps);
    const writes = writesTo(left);
    const last = (c: number) => writes.lastIndexOf(c);
    expect(writes.indexOf(Command.CHECK_PROFILE)).toBeLessThan(
      writes.indexOf(Command.PROFILE_NAME),
    );
    expect(last(Command.OBM_COPY)).toBeLessThan(writes.indexOf(Command.SWITCH_PROFILE));
    expect(writes.indexOf(Command.SWITCH_PROFILE)).toBeLessThan(
      writes.indexOf(Command.DELETE_PROFILE),
    );
    // Only the left unit's commands went to the left unit: the right one was done after it.
    expect(sent(left).length).toBeGreaterThan(0);
  });

  it('checks the Azeron app freshly before the write, the switch and each delete', async () => {
    const [left, right] = twoUnits({ slots: { 0: { name: 'Default' }, 2: { name: 'Old' } } });
    const state = await rig(left, right);
    await applyUnits(plan, state.deps);
    // Left: once to start, write, switch, the read of the other slots, two deletes, the read
    // back. Right: the same with one delete. Every step that sends the unit anything.
    expect(state.azeronCalls).toBe(7 + 6);
  });

  it('leaves the right unit untouched when the Azeron app appears between the units', async () => {
    const [left, right] = twoUnits({ slots: { 0: { name: 'Default' } } });
    const state = await rig(left, right);
    const rightBefore = right.received.length;
    let calls = 0;
    state.deps.azeronAppRunning = () => {
      // The left unit takes six looks (start, write, switch, the other slots, one delete, the
      // read back); it opens the moment it is done.
      return Promise.resolve(++calls > 6);
    };
    const result = await applyUnits(plan, state.deps);

    expect(result.ok).toBe(false);
    expect(result.units.map((u) => u.status)).toEqual(['applied', 'failed']);
    expect(result.message).toBe(result.units[1]?.message);
    expect(result.message).toBe(
      'The right unit failed: the Azeron app is open, and it talks to the units too: close it first; nothing on it was changed.',
    );
    expect(right.received).toHaveLength(rightBefore);
    expect(writesTo(right)).toEqual([]);
    expect(slotsOf(right)).toEqual([0]);
  });

  it.each([
    ['the other slots are read', 4],
    ['the layout is read back', 6],
  ])('sends the unit nothing more once the Azeron app opens before %s', async (_when, opens) => {
    const [left, right] = twoUnits({ slots: { 0: { name: 'Default' } } });
    const state = await rig(left, right);
    const rightBefore = right.received.length;
    let calls = 0;
    let at: number | undefined;
    state.deps.azeronAppRunning = () => {
      const open = ++calls >= opens;
      if (open) at ??= left.received.length;
      return Promise.resolve(open);
    };
    const result = await applyUnits(plan, state.deps);
    expect(result.ok).toBe(false);
    expect(result.message).toContain('the Azeron app is open');
    expect(left.received).toHaveLength(at ?? -1);
    expect(right.received).toHaveLength(rightBefore);
    expect(result.units[1]?.status).toBe('not-attempted');
  });

  it('touches nothing when the Azeron app is already open, and says so', async () => {
    const [left, right] = twoUnits();
    const state = await rig(left, right, { azeronAppRunning: () => Promise.resolve(true) });
    const before = [left.received.length, right.received.length];
    const result = await applyUnits(plan, state.deps);
    expect(result.ok).toBe(false);
    expect(result.units.map((u) => u.status)).toEqual(['failed', 'not-attempted']);
    expect([left.received.length, right.received.length]).toEqual(before);
  });

  it('treats a failed look at the running programs as a no', async () => {
    const [left, right] = twoUnits();
    const state = await rig(left, right, {
      azeronAppRunning: () => Promise.reject(new Error('tasklist failed')),
    });
    const before = left.received.length;
    const result = await applyUnits(plan, state.deps);
    expect(result.ok).toBe(false);
    expect(result.message).toContain('could not tell whether the Azeron app is running');
    expect(left.received).toHaveLength(before);
  });

  it('refuses a unit whose id is not the one the layout is for, and sends it nothing', async () => {
    const [left, right] = twoUnits();
    // The hands were swapped: the "left" layout meets the unit that reports the right one's id.
    const state = await rig(left, right, { ids: { left: RIGHT_ID } });
    const result = await applyUnits(plan, state.deps);
    expect(result.ok).toBe(false);
    expect(result.units.map((u) => u.status)).toEqual(['failed', 'not-attempted']);
    expect(result.message).toBe(
      'The left unit failed: this is not the unit the left layout is for; nothing on it was changed.',
    );
    expect(writesTo(left)).toEqual([]);
    expect(writesTo(right)).toEqual([]);
  });

  it('does not touch the left unit when it is the right one that is wrong, once it is its turn', async () => {
    const [left, right] = twoUnits();
    const state = await rig(left, right, { ids: { right: 1234 } });
    const result = await applyUnits(plan, state.deps);
    expect(result.units.map((u) => u.status)).toEqual(['applied', 'failed']);
    expect(writesTo(right)).toEqual([]);
    expect(result.message).toContain('The right unit failed');
  });

  it('refuses a unit that is not connected', async () => {
    const [left, right] = twoUnits();
    const state = await rig(left, right);
    state.deps.unit = () => undefined;
    const result = await applyUnits(plan, state.deps);
    expect(result.message).toBe(
      'The left unit failed: it is not connected; nothing on it was changed.',
    );
    expect(result.units[1]?.status).toBe('not-attempted');
  });

  describe('a read-back that is not clean', () => {
    const writesAfterRead = (unit: FakeUnit) =>
      sent(unit).filter((c) => c === Command.SWITCH_PROFILE || c === Command.DELETE_PROFILE);

    it('is never switched to, and nothing is deleted, when the unit stored something else', async () => {
      const left = new CorruptingUnit({
        deviceId: LEFT_ID,
        slots: { 0: { name: 'Default' }, 2: { name: 'Old' } },
        running: 0,
      });
      left.corruptSlot = 1; // the new slot goes in the gap at 1
      const right = new FakeUnit({ deviceId: RIGHT_ID });
      const state = await rig(left, right);
      const result = await applyUnits(plan, state.deps);

      expect(result.ok).toBe(false);
      expect(result.units.map((u) => u.status)).toEqual(['failed', 'not-attempted']);
      expect(result.units[0]?.wrote).toBe(true);
      expect(result.units[0]?.switched).toBe(false);
      expect(result.message).toMatch(
        /^The left unit failed: slot 1 read back differently from the layout \(1 input, first: input \d+ .+\); slot 1 is not in use, the unit still runs slot 0, and nothing was deleted\.$/,
      );
      expect(writesAfterRead(left)).toEqual([]);
      expect(left.running).toBe(0);
      expect(slotsOf(left)).toEqual([0, 1, 2]);
      expect(slotsOf(right)).toEqual([0]);
      expect(writesTo(right)).toEqual([]);
    });

    it('is the same when the unit took the writes and kept none of them', async () => {
      const left = new FakeUnit({
        deviceId: LEFT_ID,
        slots: { 0: { name: 'Default' }, 1: { name: 'Old' } },
        ignore: [Command.OBM_COPY],
      });
      const state = await rig(left, new FakeUnit({ deviceId: RIGHT_ID }));
      const result = await applyUnits(plan, state.deps);
      expect(result.ok).toBe(false);
      expect(result.message).toContain('read back differently');
