import { describe, expect, it } from 'vitest';
import type { Game, Scheme } from '@helmarray/core';
import { BUILT_IN_DEVICES, gameKeysPreset, resolve } from '@helmarray/core';
import { canonical, planFingerprint } from './plan-fingerprint';

const game: Game = {
  id: 'skiff',
  name: 'Skiff',
  modes: [{ id: 'ship', name: 'Ship' }],
  actions: [
    { id: 'boost', name: 'Boost', mode: 'ship', role: 'movement', required: true },
    { id: 'fire', name: 'Fire', mode: 'ship', role: 'combat', required: false },
  ],
  file: { format: 'elite-binds' },
};
const scheme: Scheme = {
  ...gameKeysPreset(game),
  map: { ship: { 'L.index_1': { tap: 'boost' }, 'R.index_1': { tap: 'fire' } } },
};
const plan = (s: Scheme) => resolve(s, game, BUILT_IN_DEVICES);

describe('the fingerprint of a plan', () => {
  it('is the same for the same layout, whether resolved again or read back from disk', () => {
    expect(planFingerprint(plan(scheme))).toBe(planFingerprint(plan(scheme)));
    const fromDisk = JSON.parse(JSON.stringify(plan(scheme))) as ReturnType<typeof plan>;
    expect(planFingerprint(fromDisk)).toBe(planFingerprint(plan(scheme)));
  });

  it('changes with any button, with what a button sends, and with a unit setting', () => {
    const base = planFingerprint(plan(scheme));
    const moved = {
      ...scheme,
      map: { ship: { 'L.index_1': { tap: 'fire' }, 'R.index_1': { tap: 'boost' } } },
    };
    const fewer = { ...scheme, map: { ship: { 'L.index_1': { tap: 'boost' } } } };
    const latched = { ...scheme, behaviour: { 'L.index_1': { latch: true } } };
    for (const other of [moved, fewer, latched]) {
      expect(planFingerprint(plan(other))).not.toBe(base);
    }
  });

  it('does not depend on the order of keys, nor on a key left undefined', () => {
    expect(canonical({ b: 1, a: { d: 2, c: undefined } })).toBe(canonical({ a: { d: 2 }, b: 1 }));
    expect(canonical([1, 2])).not.toBe(canonical([2, 1]));
  });
});

describe('canonical, piece by piece', () => {
  it('writes nothing as null', () => {
    expect([canonical(undefined), canonical(() => 1), canonical([undefined])]).toEqual([
      'null',
      'null',
      '[null]',
    ]);
  });

  it('joins array items and object entries with a comma', () => {
    expect([canonical([1, 2, 3]), canonical({ a: 1, b: 2 })]).toEqual(['[1,2,3]', '{"a":1,"b":2}']);
  });

  it('puts keys in order whatever order they were made in', () => {
    expect(canonical({ b: 1, c: 2, a: 3, A: 4, 10: 5, 9: 6 })).toBe(
      '{"10":5,"9":6,"A":4,"a":3,"b":1,"c":2}',
    );
  });

  it('leaves out a key whose value is undefined, and keeps one that is null', () => {
    expect(canonical({ a: undefined, b: null })).toBe('{"b":null}');
  });
});

test/unit-records.test.ts.source:
// The record encoder against every OBM_COPY the Azeron app was recorded sending. The fixtures
// hold the app's own export of each input and the bytes it sent for it; the adapter below
// turns the export into records (it is test code: helmArray builds records from its plans).
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import {
  ProtocolError,
  encodeRecord,
  fromHex,
  hostReports,
  profileNamePayload,
  toHex,
} from '@helmarray/azeron';
import type { Export } from './azeron-export';
import { adapt } from './azeron-export';

const json = <T>(path: string): T =>
  JSON.parse(readFileSync(new URL(`../reference/${path}`, import.meta.url), 'utf8')) as T;

interface Copy {
  slot: number;
  input: Export;
  frames: string[];
}

describe('every OBM_COPY the app sent', () => {
  const copies = [
    ...json<{ copies: Copy[] }>('unit-protocol/write-slot3.json').copies,
    ...json<{ copies: Copy[] }>('unit-protocol/write-112.json').copies,
  ];
  const records = json<{ records: { slot: number; input: Export; wire: string }[] }>(
    'unit-protocol/onboard-112.json',
  ).records;

  it('is a good sample: every block type and stick mode, scroll, and both units', () => {
    expect(copies.length + records.length).toBe(79);
    const all = [...copies.map((c) => c.input), ...records.map((r) => r.input)].map(adapt);
    const kinds = new Set(
      all.flatMap((r) =>
        r.kind === 'stick' ? [`stick:${r.mode}`] : [r.tap.type, r.long.type, r.double.type],
      ),
    );
    expect([...kinds].sort()).toEqual(
      [
        'disabled',
        'key',
        'mouse',
        'none',
        'pad',
        'stick:keys',
        'stick:mouse',
        'stick:pad',
        'trigger',
        'wheel',
      ].sort(),
    );
  });

  it('is rebuilt byte for byte, framed as the app framed it', () => {
    for (const copy of copies) {
      const seq = fromHex(copy.frames[0] ?? '')[3] ?? 0;
      const built = hostReports('OBM_COPY', seq, encodeRecord(copy.slot, adapt(copy.input)));
      expect(built.map(toHex), `input ${copy.input.id}`).toEqual(copy.frames);
    }
  });

  it('reproduces onboard-112.json, record by record', () => {
    for (const r of records) {
      expect(toHex(encodeRecord(r.slot, adapt(r.input))), `input ${r.input.id}`).toBe(r.wire);
    }
  });
});

describe('the profile name', () => {
  const sent = [
    json<{ profileName: string }>('unit-protocol/write-slot3.json').profileName,
    ...json<{ appCopyOverExistingSlot: { profileName: string[] } }>('unit-protocol/session2.json')
      .appCopyOverExistingSlot.profileName,
  ].map((hex) => {
    const bytes = fromHex(hex);
    const payload = bytes.slice(7, 7 + (bytes[6] ?? 0));
    return {
      hex,
      seq: bytes[3] ?? 0,
      slot: payload[0] ?? 0,
      name: String.fromCharCode(...payload.slice(2)),
    };
  });

  it('is rebuilt as the app sent it', () => {
    const fits = sent.filter((s) => s.name.length <= 19);
    expect(fits.length).toBeGreaterThan(0);
    for (const s of fits) {
      expect(
        hostReports('PROFILE_NAME', s.seq, profileNamePayload(s.slot, s.name)).map(toHex),
      ).toEqual([s.hex]);
    }
  });

  it('is refused past 19 characters, though the app sent one: the unit keeps only 19', () => {
    // "Everspace 2 akimbo v10 (right)" went out whole and was stored cut short, so reading
    // the slot back would never match what was written.
    const long = sent.filter((s) => s.name.length > 19);
    expect(long.map((s) => s.name)).toEqual(['Everspace 2 akimbo v10 (right)']);
    expect(() => profileNamePayload(long[0]?.slot ?? 0, long[0]?.name ?? '')).toThrow(
      ProtocolError,
    );
  });

  it('refuses one a unit can’t keep', () => {
    expect(() => profileNamePayload(1, '')).toThrow(ProtocolError);
    expect(() => profileNamePayload(1, 'x'.repeat(20))).toThrow(ProtocolError);
    expect(() => profileNamePayload(1, 'Café')).toThrow(ProtocolError);
    expect(profileNamePayload(1, 'x'.repeat(19))).toHaveLength(21);
  });

  it('refuses a slot that would wrap or round to another slot', () => {
    expect(() => profileNamePayload(257, 'Name')).toThrow(ProtocolError);
    expect(() => profileNamePayload(1.9, 'Name')).toThrow(ProtocolError);
    expect(() => profileNamePayload(-1, 'Name')).toThrow(ProtocolError);
    expect(profileNamePayload(5, 'Name')[0]).toBe(5);
  });
});

packages/app/src/main/hid-transport.test.source:
import { FakeUnit, UnitSession, hostReports } from '@helmarray/azeron';
import { describe, expect, it } from 'vitest';
import type { HidBackend, HidDevice, HidDeviceInfo } from './hid-transport';
import {
  UNIT_INTERFACE,
  UNIT_PRODUCT_ID,
  UNIT_USAGE_PAGE,
  UNIT_VENDOR_ID,
  findUnits,
  openUnit,
} from './hid-transport';

const unitInterface = (path: string, over: Partial<HidDeviceInfo> = {}): HidDeviceInfo => ({
  vendorId: UNIT_VENDOR_ID,
  productId: UNIT_PRODUCT_ID,
  usagePage: UNIT_USAGE_PAGE,
  interface: UNIT_INTERFACE,
  path,
  ...over,
});

const LEFT = '\\\\?\\hid#vid_16d0&pid_12f7&mi_04#left';
const RIGHT = '\\\\?\\hid#vid_16d0&pid_12f7&mi_04#right';
const KEYBOARD_INTERFACE = '\\\\?\\hid#vid_16d0&pid_12f7&mi_00#left';
const PEDALS = '\\\\?\\hid#vid_06a3&pid_0763#pedals';

/** Everything a Windows enumeration would list: two units, their other interfaces, the pedals. */
const everything: HidDeviceInfo[] = [
  unitInterface(KEYBOARD_INTERFACE, { usagePage: 0x01, interface: 0 }),
  unitInterface(LEFT),
  unitInterface(RIGHT),
  unitInterface('\\\\?\\hid#vid_16d0&pid_12f7&mi_01#left', { usagePage: 0x0c, interface: 1 }),
  { vendorId: 0x06a3, productId: 0x0763, usagePage: 0x01, interface: 0, path: PEDALS },
];

/** A fake node-hid: hidapi's filter, a device list, and a log of everything done to it. */
class FakeBackend implements HidBackend {
  readonly enumerated: [number, number][] = [];
  readonly opened: string[] = [];
  readonly devices = new Map<string, HidDevice>();

  constructor(private readonly list: HidDeviceInfo[] = everything) {}

  async enumerate(vendorId: number, productId: number) {
    this.enumerated.push([vendorId, productId]);
    // As hidapi does: a filter that doesn't match lists nothing; no filter lists everything.
    return this.list.filter((d) => d.vendorId === vendorId && d.productId === productId);
  }

  async open(path: string) {
    this.opened.push(path);
    const device = this.devices.get(path);
    if (!device) throw new Error(`nothing at ${path}`);
    return device;
  }
}

/** An open device that records its writes and plays back the reports it is given. */
class ScriptedDevice implements HidDevice {
  readonly written: Uint8Array[] = [];
  readonly reads: number[] = [];
  closed = 0;
  constructor(private readonly incoming: (Uint8Array | undefined)[] = []) {}
  async write(data: Uint8Array) {
    this.written.push(data);
  }
  async read(timeoutMs: number) {
    this.reads.push(timeoutMs);
    return this.incoming.shift();
  }
  async close() {
    this.closed++;
  }
}

const withDevice = (device: HidDevice, path = LEFT) => {
  const backend = new FakeBackend();
  backend.devices.set(path, device);
  return backend;
};

describe('finding units', () => {
  it('enumerates with the unit’s vendor and product id, never unfiltered', async () => {
    const backend = new FakeBackend();
    await findUnits(backend);
    expect(backend.enumerated).toEqual([[0x16d0, 0x12f7]]);
  });

  it('returns only the configuration interface of each unit', async () => {
    expect(await findUnits(new FakeBackend())).toEqual([{ path: LEFT }, { path: RIGHT }]);
  });

  it('leaves out the pedals, the units’ other interfaces and anything without a path', async () => {
    const backend = new FakeBackend([
      ...everything.filter((d) => d.path !== LEFT && d.path !== RIGHT),
      unitInterface('', {}),
      unitInterface('x', { path: undefined }),
      unitInterface('wrong page', { usagePage: 0x01 }),
      unitInterface('wrong interface', { interface: 3 }),
    ]);
    expect(await findUnits(backend)).toEqual([]);
  });

  it('finds nothing when no unit is plugged in', async () => {
    const pedalsOnly = new FakeBackend(everything.filter((d) => d.vendorId === 0x06a3));
    expect(await findUnits(pedalsOnly)).toEqual([]);
  });
});

describe('opening a unit', () => {
  it('opens a path findUnits returned', async () => {
    const backend = withDevice(new ScriptedDevice());
    await openUnit(backend, LEFT);
    expect(backend.opened).toEqual([LEFT]);
  });

  it.each([
    ['the pedals', PEDALS],
    ['a unit’s other interface', KEYBOARD_INTERFACE],
    ['a path nobody listed', '\\\\?\\hid#vid_dead&pid_beef#x'],
    ['an empty path', ''],
  ])('refuses %s, and opens nothing', async (_name, path) => {
    const backend = new FakeBackend();
    backend.devices.set(path, new ScriptedDevice());
    await expect(openUnit(backend, path)).rejects.toThrow(/not an Azeron unit/);
    expect(backend.opened).toEqual([]);
  });

  it('refuses a unit that was unplugged since it was found', async () => {
    const backend = new FakeBackend([]);
    backend.devices.set(LEFT, new ScriptedDevice());
    await expect(openUnit(backend, LEFT)).rejects.toThrow(/not an Azeron unit/);
    expect(backend.opened).toEqual([]);
  });

  it('checks the path against a filtered enumeration too', async () => {
    const backend = withDevice(new ScriptedDevice());
    await openUnit(backend, LEFT);
    expect(backend.enumerated).toEqual([[0x16d0, 0x12f7]]);
  });
});

describe('the transport', () => {
  const report = (...head: number[]) => {
    const r = new Uint8Array(64);
    r.set(head);
    return r;
  };

  it('writes report id 0 ahead of the whole 64-byte frame, which goes on the wire as it is', async () => {
    // hidapi takes the first byte written as the report id and puts only the rest on the wire.
    // The app's own frames start with a 0 that is data (112-write.pcap: `00 00 12 ba 01 01 …`),
    // so without the extra id byte every command reached the unit one byte short and was ignored.
    const device = new ScriptedDevice();
    const unit = await openUnit(withDevice(device), LEFT);
    const frame = hostReports('FIRMWARE_VERSION', 7, new Uint8Array())[0] as Uint8Array;
    await unit.send(frame);
    expect(device.written).toHaveLength(1);
    const written = device.written[0] as Uint8Array;
    expect(written).toHaveLength(65);
    expect(written[0]).toBe(0);
    const wire = Array.from(written.slice(1));
    expect(wire).toEqual(Array.from(frame));
    expect(wire.slice(0, 6)).toEqual([0x00, 0x00, 0x05, 7, 0x01, 0x01]);
  });

  it('refuses to send anything that is not a 64-byte report', async () => {
    const device = new ScriptedDevice();
    const unit = await openUnit(withDevice(device), LEFT);
    await expect(unit.send(new Uint8Array(65))).rejects.toThrow(/64 bytes/);
    await expect(unit.send(new Uint8Array(0))).rejects.toThrow(/64 bytes/);
    expect(device.written).toEqual([]);
  });

  it('receives the next report as a Uint8Array, asking the device for the timeout given', async () => {
    const device = new ScriptedDevice([report(1, 2, 3)]);
    const unit = await openUnit(withDevice(device), LEFT);
    const got = await unit.receive(250);
    expect(got).toBeInstanceOf(Uint8Array);
    expect(Array.from(got ?? []).slice(0, 4)).toEqual([1, 2, 3, 0]);
    expect(got).toHaveLength(64);
    expect(device.reads).toEqual([250]);
  });

  it('gives null when nothing comes in time, whether the device says undefined or empty', async () => {
    const device = new ScriptedDevice([undefined, new Uint8Array(0)]);
    const unit = await openUnit(withDevice(device), LEFT);
    expect(await unit.receive(10)).toBeNull();
    expect(await unit.receive(10)).toBeNull();
  });

  it('never asks the device to wait without limit', async () => {
    const device = new ScriptedDevice([undefined, undefined]);
    const unit = await openUnit(withDevice(device), LEFT);
    await unit.receive(-1);
    await unit.receive(12.7);
    expect(device.reads).toEqual([0, 12]);
  });

  it('closes the device once, and does nothing more afterwards', async () => {
    const device = new ScriptedDevice();
    const unit = await openUnit(withDevice(device), LEFT);
    await unit.close();
    await unit.close();
    expect(device.closed).toBe(1);
    await expect(unit.send(report())).rejects.toThrow(/closed/);
    await expect(unit.receive(10)).rejects.toThrow(/closed/);
    expect(device.written).toEqual([]);
    expect(device.reads).toEqual([]);
  });

  it('passes a failed write on to the caller', async () => {
    const device = new ScriptedDevice();
    device.write = () => Promise.reject(new Error('unplugged'));
    const unit = await openUnit(withDevice(device), LEFT);
    await expect(unit.send(report())).rejects.toThrow('unplugged');
  });
});

describe('a session over the transport', () => {
  it('identifies a unit that answers as a Cyborg II does', async () => {
    const fake = new FakeUnit({ deviceId: 49229 });
    // As hidapi does: the first byte written is the report id, and only the rest reaches the unit.
    const device: HidDevice = {
      write: async (data) => {
        if (data[0] !== 0) throw new Error(`report id ${data[0]}, not 0`);
        await fake.send(data.slice(1));
      },
      read: async () => (await fake.receive()) ?? undefined,
      close: async () => undefined,
    };
    const [unit] = await findUnits(withDevice(device));
    const transport = await openUnit(withDevice(device), unit?.path ?? '');
    const identity = await new UnitSession(transport).identify();
    expect(identity).toMatchObject({ firmware: 112, deviceId: 49229, slotLimit: 6 });
    expect(fake.received.length).toBeGreaterThan(0);
    await transport.close();
  });
});

test/unit-profile.test.ts.source:
// A plan's unit profile into records, against what the Azeron app wrote for the owner's own
// layouts: the input ids every slot holds, and the bytes of each input a plan can express.
import { readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';
import type { KeyCode, PinPlan, Signal, UnitProfile } from '@helmarray/core';
import { CYBORG2_LEFT, CYBORG2_RIGHT } from '@helmarray/core';
import {
  INPUT_ID_BY_PIN,
  UNIT_KEY_CODES,
  encodeRecord,
  fromHex,
  toHex,
  unitRecords,
} from '@helmarray/azeron';

const json = <T>(path: string): T =>
  JSON.parse(readFileSync(new URL(`../reference/${path}`, import.meta.url), 'utf8')) as T;

interface Input {
  id: number;
  pinOne: number;
  pinTwo: number;
  types: string[];
  keyValues: string[];
  metaValues: string[];
  keyValuesLong: string[];
  keyValuesDouble: string[];
  analogSettings?: Record<string, unknown>;
}

const inputs = (path: string, key: 'copies' | 'records' | 'decoded'): Input[] => {
  const doc = json<Record<string, unknown[]>>(path);
  if (key === 'decoded') return (doc[key] as { inputs: Input[] }[]).flatMap((p) => p.inputs);
  return (doc[key] as { input: Input }[]).map((c) => c.input);
};

const everyInput = [
  ...inputs('unit-protocol/write-slot3.json', 'copies'),
  ...inputs('unit-protocol/write-112.json', 'copies'),
  ...inputs('unit-protocol/onboard-112.json', 'records'),
  ...inputs('unit-protocol/read-all.json', 'decoded'),
  ...json<{ profiles: { inputs: Input[] }[] }>(
    'unit-exports/everspace2-akimbo-left.json',
  ).profiles.flatMap((p) => p.inputs),
  ...json<{ profiles: { inputs: Input[] }[] }>(
    'unit-exports/everspace2-akimbo-right.json',
  ).profiles.flatMap((p) => p.inputs),
];

describe('input ids', () => {
  it('are the ones every slot in reference/ holds, on both units', () => {
    const written = everyInput.filter((i) => i.pinOne !== 255 && i.pinOne !== 0);
    expect(written.length).toBeGreaterThan(200);
    for (const input of written) {
      if ([28, 29].includes(input.pinOne)) continue; // unknown pins: never written
      expect(INPUT_ID_BY_PIN.get(input.pinOne), `pin ${input.pinOne}`).toBe(input.id);
    }
  });

  it('cover every pin of both units but the unknown ones and the profile switch', () => {
    for (const unit of [CYBORG2_LEFT, CYBORG2_RIGHT]) {
      const pins = unit.positions.map((p) => p.pin).sort((a, b) => a - b);
      expect(pins.every((p) => INPUT_ID_BY_PIN.has(p))).toBe(true);
      expect([...INPUT_ID_BY_PIN.keys()].sort((a, b) => a - b)).toEqual(pins);
    }
  });
});

// The app's key names for the keys the owner's layout uses, in core's names.
const CORE_NAMES: Record<string, KeyCode> = {
  Escape: 'Esc',
  Tab: 'Tab',
  Equal: '=',
};
const coreKey = (name: string): KeyCode =>
  CORE_NAMES[name] ??
  ((name.startsWith('Key') || name.startsWith('Digit')
    ? name.replace(/^(Key|Digit)/, '')
    : name) as KeyCode);

describe("the owner's Everspace 2 layout (left unit, slot 4)", () => {
  const copies = json<{ copies: { slot: number; input: Input; frames: string[] }[] }>(
    'unit-protocol/write-112.json',
  ).copies;
  // What a plan can say: one key or a mouse button per press, no modifiers alone, and no
  // Disabled presses (2.0.3 writes an empty press as 6; helmArray writes it as 11, as 2.0.2 did).
  const expressible = copies.filter(
    ({ input }) =>
      input.pinTwo === 255 &&
      input.types.every((t) => t === '1' || t === '11' || (t === '15' && input.types[0] === t)) &&
      input.keyValues.some((k) => k !== '0'),
  );

  const signal = (type: string | undefined, keys: string[]): Signal | undefined => {
    const key = keys.find((k) => k !== '0');
    if (key === undefined) return undefined;
    if (type === '15')
      return { kind: 'mouse', button: key === '1' ? 'left' : key === '3' ? 'right' : 'middle' };
    return { kind: 'key', code: coreKey(key) };
  };

  const pins: PinPlan[] = CYBORG2_LEFT.positions
    .filter((p) => p.name !== 'stick')
    .map((p) => {
      const input = expressible.find((c) => c.input.pinOne === p.pin)?.input;
      const presses: PinPlan['presses'] = {};
      const tap = input && signal(input.types[0], input.keyValues);
      const long = input && signal(input.types[1], input.keyValuesLong);
      const double = input && signal(input.types[2], input.keyValuesDouble);
      if (tap) presses.tap = tap;
      if (long) presses.long = long;
      if (double) presses.double = double;
      return {
        control: `L.${p.name}`,
        position: p.name,
        pin: p.pin,
        presses,
        turbo: false,
        latch: false,
      };
    });
  const profile: UnitProfile = {
    deviceId: CYBORG2_LEFT.id,
    hand: 'left',
    pins,
    stick: { mode: 'keys', angle: 0, invertX: false },
  };
  const records = unitRecords(profile, CYBORG2_LEFT);

  it('is a good sample: 23 of its 31 inputs, a mouse button and long and double presses among them', () => {
    expect(expressible).toHaveLength(23);
    expect(expressible.some((c) => c.input.types[0] === '15')).toBe(true);
    expect(expressible.some((c) => c.input.keyValuesLong.some((k) => k !== '0'))).toBe(true);
    expect(expressible.some((c) => c.input.keyValuesDouble.some((k) => k !== '0'))).toBe(true);
  });

  it('comes out byte for byte as the app wrote each of those inputs', () => {
    for (const { slot, input, frames } of expressible) {
      const record = records.find((r) => r.id === input.id);
      const sent = frames.map(fromHex).flatMap((f) => [...f.slice(7, 7 + (f[6] ?? 0))]);
      expect(record && toHex(encodeRecord(slot, record)), `input ${input.id}`).toBe(
        toHex(Uint8Array.from(sent)),
      );
    }
  });

  it('writes one record per input, in id order, and none for the unknown pins', () => {
    expect(records.map((r) => r.id)).toEqual([...INPUT_ID_BY_PIN.values()].sort((a, b) => a - b));
    expect(records.some((r) => [28, 29, 0].includes(r.pinOne))).toBe(false);
  });
});

describe('the stick', () => {
  const pins: PinPlan[] = [];
  const left = (stick: UnitProfile['stick']): UnitProfile => ({
    deviceId: CYBORG2_LEFT.id,
    hand: 'left',
    pins,
    stick,
  });

  it("as the left unit's Xbox stick, tunes as the app wrote it", () => {
    const sent = json<{ records: { capture: string; slot: number; input: Input; wire: string }[] }>(
      'unit-protocol/onboard-112.json',
    ).records.find((r) => r.capture === 'xinput' && r.input.pinTwo === 30);
    const stick = unitRecords(
      left({ mode: 'pad-left', angle: 0, invertX: false }),
      CYBORG2_LEFT,
    ).find((r) => r.kind === 'stick');
    // The directions after byte 38 are keys the template left behind; an Xbox stick ignores them.
    expect(stick && toHex(encodeRecord(sent?.slot ?? 0, stick)).slice(0, 76)).toBe(
      sent?.wire.slice(0, 76),
    );
  });

  it('as a mouse, tunes as the app wrote the owner’s “super sensitive” stick', () => {
    const sent = json<{ records: { capture: string; slot: number; input: Input; wire: string }[] }>(
      'unit-protocol/onboard-112.json',
    ).records.find((r) => r.capture === 'joystick-mouse' && r.input.pinTwo === 30);
    const stick = unitRecords(
      left({ mode: 'mouse', sensitivity: 2, angle: 5, invertX: false }),
      CYBORG2_LEFT,
    ).find((r) => r.kind === 'stick');
    // Header and tuning: the directions after byte 38 are keys the template left behind.
    expect(stick && toHex(encodeRecord(sent?.slot ?? 0, stick)).slice(0, 76)).toBe(
      sent?.wire.slice(0, 76),
    );
  });
});

describe('the key table', () => {
  it('gives every key the unit code of its HID usage', () => {
    expect(UNIT_KEY_CODES.A).toBe(0xf004);
    expect(UNIT_KEY_CODES.Z).toBe(0xf01d);
    expect(UNIT_KEY_CODES['1']).toBe(0xf01e);
    expect(UNIT_KEY_CODES['0']).toBe(0xf027);
    expect(UNIT_KEY_CODES.F12).toBe(0xf045);
    expect(UNIT_KEY_CODES.F13).toBe(0xf068);
    expect(UNIT_KEY_CODES.Insert).toBe(0xf049);
    expect(UNIT_KEY_CODES.LShift).toBe(0xe002);
    expect(new Set(Object.values(UNIT_KEY_CODES)).size).toBe(Object.keys(UNIT_KEY_CODES).length);
  });
});

